const fmtISO=iso=>{const p=iso.split('-');if(p.length===1||isNaN(+p[1]))return iso;const [y,m,d]=p.map(Number);return d?`${MONTHS[m-1].slice(0,3)} ${d}, ${y}`:`${MONTHS[m-1].slice(0,3)} ${y}`};
