  const hs=$$(`[data-heat="${q.id}"]`);if(hs.length){hs.forEach(h=>h.outerHTML=heatTile(q));const b=$('#breadth');if(b)b.textContent=breadth();const b2=$('#breadth2');if(b2)b2.textContent=breadth()}
  if(q.g==='rt'&&$('#yc'))$('#yc').innerHTML=yieldCurve();
