function avatar(d,size=40){return `<span class="xav" style="--dc:${d.hex};width:${size}px;height:${size}px">${d.pfp?`<img src="${d.pfp}" alt="">`:`<img src="${d.logo==='silver'?LOGOS72:LOGO72}" alt="">`}</span>`}
function xMenuHTML(){return `<div class="xm-h"><span class="mono dim">OUR TWO ACCOUNTS ON X</span></div>${[['hub',DESKS.hub],['then',DESKS.then]].map(([k,d])=>`<a class="xm-i" href="${xUrl(d.handle)}" target="_blank" rel="noopener" role="menuitem" style="--dc:${d.hex}">${avatar(d)}<span class="xm-t"><b>${k==='hub'?'Market Files':esc(d.name)}</b><span class="mono">@${d.handle}</span><small>${esc(k==='hub'?'Markets, money and the news of the day — live.':'Financial history — the past, told as it happened.')}</small></span><span class="xm-f">Follow</span></a>`).join('')}`}
function wireXMenu(){const b=$('#x-b'),m=$('#x-m');if(!b||!m)return;m.innerHTML=xMenuHTML();
  const close=()=>{m.hidden=true;b.setAttribute('aria-expanded','false')};
  b.onclick=e=>{e.stopPropagation();const open=m.hidden;m.hidden=!open;b.setAttribute('aria-expanded',String(open));if(open)$('a',m).focus()};
  document.addEventListener('click',e=>{if(!m.hidden&&!m.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden){close();b.focus()}})}

/* ---------- home ---------- */
const PLATFORMS=[];
function wrapLine(){const g=id=>INSTR.find(q=>q.id===id),ok=q=>q&&!q.na,p=q=>(q.v-q.prev)/q.prev*100;
  const eq=['SPX','COMP','INDU'].map(g).filter(ok).map(p);if(!eq.length)return Feed.live?'Waiting for the first live prices…':'Loading the board…';
  const up=eq.filter(x=>x>0).length;let st=up===eq.length?'Stocks are higher':up===0?'Stocks are lower':'Stocks are mixed';
  const es=g('ES1');if(ok(es)&&session('eq').c!=='open'){const e=p(es);st=`S&P 500 futures are ${Math.abs(e)<.05?'flat':`${e>0?'up':'down'} ${Math.abs(e).toFixed(2)}%`}, pointing to a ${Math.abs(e)<.05?'flat':e>0?'higher':'lower'} open`}
  const mv=(x,u,d)=>Math.abs(x)<.05?'flat':(x>0?u:d);const bits=[];
  const t10=g('US10Y');if(ok(t10)){const y=(t10.v-t10.prev)*100;bits.push(`the 10-year yield is ${Math.abs(y)<.5?'little changed':`${y>0?'up':'down'} ${Math.abs(y).toFixed(1)}bp`}`)}
  const dx=g('DXY');if(ok(dx))bits.push(`the dollar is ${mv(p(dx),'firmer','softer')}`);
  const oil=g('CL');if(ok(oil))bits.push(`oil is ${mv(p(oil),'up','down')} ${Math.abs(p(oil)).toFixed(1)}%`);
  const au=g('XAU');if(ok(au))bits.push(`gold is ${mv(p(au),'up','down')} ${Math.abs(p(au)).toFixed(1)}%`);
  const bt=g('BTC');if(ok(bt))bits.push(`bitcoin is ${mv(p(bt),'up','down')} ${Math.abs(p(bt)).toFixed(1)}%`);
  if(!bits.length)return st+'.';const last=bits.pop();const txt=(bits.length?bits.join(', ')+' and ':'')+last;return `${st}. ${txt[0].toUpperCase()+txt.slice(1)}.`}
const KT=['SPX','COMP','INDU','US10Y','XAU','CL','EURUSD','BTC'];
function keyTiles(){return `<div class="kts">${qs(KT).map(q=>{const c=chg(q);return `<div class="kt" data-id="${q.id}" ${rowAttr(q)} data-holo><span class="kt-n">${esc(q.name)}</span><span class="kt-v mono" data-f="v">${fmtV(q)}</span><span class="kt-c mono c ${c.cls}" data-f="c">${c.arrow} ${c.txt}</span>${spark(q)}</div>`}).join('')}</div>`}
/* ---------- tabs ---------- */
const TAB_MEM={};
function tabsHTML(id,items,cls=''){const cur=TAB_MEM[id]&&items.some(i=>i[0]===TAB_MEM[id])?TAB_MEM[id]:items[0][0];
  return `<div class="tabs ${cls}" id="${id}" data-tabs><div class="tabs-bar" role="tablist">${items.map(([k,l])=>`<button type="button" class="tab" role="tab" data-tab="${k}" id="${id}-t-${k}" aria-controls="${id}-p-${k}" aria-selected="${k===cur}" tabindex="${k===cur?0:-1}">${l}</button>`).join('')}</div>${items.map(([k,l,h])=>`<div class="tabp" role="tabpanel" id="${id}-p-${k}" aria-labelledby="${id}-t-${k}" ${k===cur?'':'hidden'}>${h}</div>`).join('')}</div>`}
function showTab(t,k,focus){const id=t.id;TAB_MEM[id]=k;
  [...t.children].forEach(c=>{if(c.classList.contains('tabs-bar'))[...c.children].forEach(b=>{const on=b.dataset.tab===k;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;if(on&&focus)b.focus()});else if(c.classList.contains('tabp'))c.hidden=c.id!==`${id}-p-${k}`});
  tabShown(id,k)}
function tabShown(id,k){if(typeof mountCryptoTV==='function')mountCryptoTV();if(typeof mountTVFutures==='function')mountTVFutures();if(typeof mountHeatmaps==='function')mountHeatmaps();if(typeof mountTVMain==='function')mountTVMain()}
function wireTabs(root){$$('[data-tabs]',root||document).forEach(t=>{if(t._w)return;t._w=1;const bar=[...t.children].find(c=>c.classList.contains('tabs-bar'));
  bar.onclick=e=>{const b=e.target.closest('.tab');if(b)showTab(t,b.dataset.tab)};
  bar.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...bar.children];let i=tabs.findIndex(b=>b.getAttribute('aria-selected')==='true');i=e.key==='ArrowRight'?(i+1)%tabs.length:e.key==='ArrowLeft'?(i-1+tabs.length)%tabs.length:e.key==='Home'?0:tabs.length-1;showTab(t,tabs[i].dataset.tab,true)}})}

/* ---------- headlines slideshow (real headlines via /api/news; sample stories only in the preview) ---------- */
const HL={items:[],i:0,src:'',timer:0,paused:false};
const ago=iso=>{const m=Math.max(1,Math.round((Date.now()-new Date(iso))/6e4));return m<60?m+'m ago':m<1440?Math.round(m/60)+'h ago':Math.round(m/1440)+'d ago'};
function headlinesHTML(){return `<section class="pnl hl" data-holo id="hl" aria-label="Market headlines"><div class="pnl-h"><h3>Headlines</h3><span class="sess mono" id="hl-src"></span></div><div class="hl-b" id="hl-b"></div><div class="hl-c"><button class="ib" data-hl="-1" aria-label="Previous headline">‹</button><span class="hl-dots" id="hl-dots"></span><button class="ib" data-hl="1" aria-label="Next headline">›</button></div></section>`}
function hlRender(){const b=$('#hl-b');if(!b)return;const it=HL.items[HL.i];
  if(!it){b.innerHTML=`<div class="hl-i"><span class="mono dim">HEADLINES</span><h3>Loading the latest market headlines…</h3><a class="readfile" href="https://news.google.com/search?q=stock%20market" target="_blank" rel="noopener">Open Google News <span aria-hidden="true">↗</span></a></div>`;return}
  const ext=!it.internal;b.innerHTML=`<a class="hl-i" href="${esc(it.link)}" ${ext?'target="_blank" rel="noopener"':''}><span class="mono dim">${esc(it.source)}${it.when?' · '+ago(it.when):''}</span><h3>${esc(it.title)}</h3><span class="readfile">${ext?`Read at ${esc(it.source)} <span aria-hidden="true">↗</span>`:'Read file <span aria-hidden="true">→</span>'}</span></a>`;
  const d=$('#hl-dots');if(d)d.innerHTML=HL.items.map((_,i)=>`<i class="${i===HL.i?'on':''}"></i>`).join('');const s=$('#hl-src');if(s)s.textContent=HL.src}
async function startHeadlines(){const h=$('#hl');if(!h)return;hlRender();
  if(!HL.items.length){try{const r=await fetch('/api/news');if(r.ok){const j=await r.json();if(j.items&&j.items.length){HL.items=j.items.slice(0,10);HL.src='GOOGLE NEWS · LIVE'}}}catch(e){}}
  if(!HL.items.length&&typeof LIVE!=='undefined'&&LIVE.length){HL.items=LIVE.slice(0,6).map(a=>({title:a.head,source:'Market Files',link:'#/file/'+a.slug,when:a.when.toISOString(),internal:true}));HL.src='SAMPLE STORIES · PREVIEW'}
  HL.i=0;hlRender();
  const go=n=>{if(!HL.items.length)return;HL.i=(HL.i+n+HL.items.length)%HL.items.length;hlRender()};
  h.onclick=e=>{const b=e.target.closest('[data-hl]');if(b){e.preventDefault();go(+b.dataset.hl)}};
  h.onmouseenter=h.onfocusin=()=>HL.paused=true;h.onmouseleave=h.onfocusout=()=>HL.paused=false;
  clearInterval(HL.timer);if(!RM){HL.timer=setInterval(()=>{if(!HL.paused&&document.getElementById('hl'))go(1)},8000);cleanup.push(()=>clearInterval(HL.timer))}}

