const dxMoney=v=>v>=1e9?`$${(v/1e9).toFixed(2)}B`:v>=1e6?`$${(v/1e6).toFixed(1)}M`:`$${Math.round(v/1e3)}K`;
const dxPx=p=>p>=1?'$'+p.toLocaleString('en-US',{maximumFractionDigits:2}):'$'+p.toFixed(Math.min(10,3-Math.floor(Math.log10(p))));
function dexPanel(){return `<div class="wrap data-desk"><section class="pnl dx" id="dx" data-holo style="display:none"><div class="pnl-h"><h3>Active on-chain tokens</h3><span class="sess mono">Data: DEX Screener · ranked by 24h volume</span></div><div class="tscroll" id="dx-b"></div><p class="dx-note mono dim">Meme and low-cap tokens are extremely volatile and can go to zero or be scams. Liquidity, volume and age filters are applied, but appearing here is not an endorsement. Not financial advice.</p></section></div>`}
function dexRows(it){return `<table class="crt"><thead><tr><th>#</th><th>Token</th><th>Price</th><th>24h</th><th>Volume 24h</th><th>Liquidity</th><th>Open in</th></tr></thead><tbody>${it.map((x,i)=>{const c=x.change24h;
  return `<tr><td class="mono dim">${i+1}</td><td>${x.image?`<img class="dx-ic" src="${esc(x.image)}" alt="" width="22" height="22" loading="lazy" referrerpolicy="no-referrer">`:''}<b>${esc(x.symbol)}</b> <span class="mono dim">${esc(x.name)} · ${esc(x.chain.toUpperCase())}</span></td><td class="mono">${dxPx(x.price)}</td><td class="mono ${c==null?'dim':c>=0?'up':'dn'}">${c==null?'—':(c>=0?'▲ +':'▼ ')+c.toFixed(1)+'%'}</td><td class="mono">${dxMoney(x.volume24h)}</td><td class="mono">${dxMoney(x.liquidity)}</td><td class="dx-lk"><a href="${esc(x.dexscreener)}" target="_blank" rel="noopener noreferrer">DEX Screener ↗</a>${x.dextools?`<a href="${esc(x.dextools)}" target="_blank" rel="noopener noreferrer">DEXTools ↗</a>`:''}${x.phantom?`<a href="${esc(x.phantom)}" target="_blank" rel="noopener noreferrer">Phantom ↗</a>`:''}</td></tr>`}).join('')}</tbody></table>`}
async function wireDex(){const s=$('#dx');if(!s)return;try{const r=await fetch('/api/dex');if(!r.ok)return;const j=await r.json();const it=(j&&j.items)||[];if(!it.length||!$('#dx'))return;$('#dx-b').innerHTML=dexRows(it);s.style.display=''}catch(e){}}
const heatGrid=(ids,title)=>`<section class="pnl" data-holo><div class="pnl-h"><h3>${title}</h3><span class="sess mono">Green up · red down · grey = no data</span></div><div class="heat heat-w">${ids.map(heatTile).join('')}</div></section>`;
