let CO_SECTOR='all',CO_Q='';
function coRow(q){const c=chg(q);return `<tr class="cr-row" data-id="${q.id}" ${rowAttr(q)}><td>${coLogo(q.id,36)}</td><td><b>${esc(q.name)}</b> <span class="mono dim">${esc(q.id)}</span></td><td class="mono dim co-s">${esc((CO_SECT.find(s=>s[0]===q.sec)||[0,''])[1])}</td><td class="mono" data-f="v">${q.na?'—':'$'+fmtV(q)}</td><td class="mono c ${c.cls}" data-f="c">${c.arrow} ${c.txt}</td><td>${spark(q)}</td><td class="lks"><a href="${tvUrl(q.id)}" target="_blank" rel="noopener">TV ↗</a><a href="${gq(q.name+' stock')}" target="_blank" rel="noopener">Google ↗</a><a href="https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=${encodeURIComponent(q.id.replace('.','-'))}&type=10-K&dateb=&owner=include&count=10" target="_blank" rel="noopener">SEC ↗</a></td></tr>`}
function coTable(){const list=INSTR.filter(q=>q.g==='co'&&(CO_SECTOR==='all'||q.sec===CO_SECTOR)&&(!CO_Q||(q.name+' '+q.id).toLowerCase().includes(CO_Q)));
  return `<table class="crt co-t"><thead><tr><th><span class="sr">Logo</span></th><th>Company</th><th>Sector</th><th>Price</th><th>Day</th><th>Trend</th><th><span class="sr">Links</span></th></tr></thead><tbody>${list.map(coRow).join('')||'<tr><td colspan="7" class="dim" style="padding:24px">No company matches. <a href="'+gq(CO_Q+' stock')+'" target="_blank" rel="noopener" style="text-decoration:underline">Search Google for “'+esc(CO_Q)+'” ↗</a></td></tr>'}</tbody></table>`}
function pageCompanies(){setMeta('Companies — Market Files','Prices, charts, filings and history for the biggest listed companies.');
  return `<div class="wrap page-in" style="--dc:#E8B84A"><header class="ph"><h1>Companies</h1><p>The biggest listed companies, with live prices, charts, SEC filings and the history behind each. Prices are delayed; “—” means no data right now.</p></header>
  <div class="co-bar"><div class="tabs-bar co-tabs" role="tablist" id="co-tabs">${[['all','All'],...CO_SECT].map(([k,l])=>`<button type="button" class="tab" role="tab" data-co="${k}" aria-selected="${k===CO_SECTOR}">${l}</button>`).join('')}</div><label class="sr" for="co-q">Find a company</label><input class="inp co-q" id="co-q" placeholder="Find a company or ticker…" autocomplete="off" value="${esc(CO_Q)}"></div>
  <section class="pnl" data-holo><div class="pnl-h"><h3>U.S. listed · large caps</h3><span class="sess mono">Click a row for the chart · TV = TradingView · SEC = filings</span></div><div class="tscroll" id="co-tbl">${coTable()}</div></section>
  <p class="pv">Market Files is a news and media company. Company pages are educational and are not recommendations to buy or sell any security.</p></div>`}
function wireCompanies(){const tb=$('#co-tbl');const redo=()=>{tb.innerHTML=coTable();attachHolo()};
  $('#co-tabs').onclick=e=>{const b=e.target.closest('[data-co]');if(!b)return;CO_SECTOR=b.dataset.co;$$('#co-tabs .tab').forEach(x=>x.setAttribute('aria-selected',x===b));redo()};
  $('#co-q').oninput=e=>{CO_Q=e.target.value.trim().toLowerCase();redo()};
  if(typeof Feed.want==='function')Feed.want('companies')}

/* section pages */
const SECTIONS={
 latest:{title:'Latest',desc:'Everything filed across the Market Files desks.',filter:()=>[...LIVE,...[...HIST].sort((a,b)=>b.date.localeCompare(a.date))]},
 'wall-street':{title:'Wall Street',desk:'wallst',filter:()=>[...LIVE.filter(a=>a.desk==='wallst'),...HIST.filter(a=>a.desk==='then').sort((a,b)=>b.date.localeCompare(a.date))]},
 'global-finance':{title:'Global',desk:'global',filter:()=>A.filter(a=>a.desk==='global').sort((a,b)=>(b.type==='live')-(a.type==='live')||b.date.localeCompare(a.date))},
 history:{title:'History',desk:'then',serif:true,desc:'Financial history from every desk, from the Dutch East India Company to spot bitcoin ETFs.',filter:()=>[...HIST].sort((a,b)=>b.date.localeCompare(a.date))},
 crypto:{title:'Crypto',desk:'btc',desc:'Bitcoin, Ethereum and the digital-asset market — live prices, history and the files behind them.',filter:()=>A.filter(a=>a.desk==='btc'||a.desk==='chain').sort((a,b)=>(b.type==='live')-(a.type==='live')||b.date.localeCompare(a.date))},
 bitcoin:{title:'Bitcoin',desk:'btc',filter:()=>A.filter(a=>a.desk==='btc').sort((a,b)=>(b.type==='live')-(a.type==='live')||b.date.localeCompare(a.date))},
 blockchain:{title:'Blockchain',desk:'chain',filter:()=>A.filter(a=>a.desk==='chain').sort((a,b)=>(b.type==='live')-(a.type==='live')||b.date.localeCompare(a.date))},
 research:{title:'Research',serif:true,desc:'Deep reads on the mechanisms behind the events that changed markets.',filter:()=>HIST.filter(a=>a.research)}
};
function pageSection(key){const s=SECTIONS[key];const d=s.desk?DESKS[s.desk]:null;const list=s.filter();const dc=d?d.hex:'#E9EDF2';
  setMeta(`${s.title} — Market Files`,s.desc||d?.blurb||'');
  const extra=key==='wall-street'?`<p class="pv" style="margin-top:14px">History from this beat is filed by ${handleLink(DESKS.then)}.</p>`:'';
  return `<div class="wrap page-in" style="--dc:${dc}"><header class="ph ${s.serif?'serif':''}"><h1>${s.title}</h1><p>${esc(s.desc||d.blurb)}</p>${d?`<div class="sec-a">${handleLink(d)}</div>`:''}${extra}</header>
  ${stripTiles(DESK_INST[key]||[])}<div style="height:28px"></div>${list.length?`<div class="grid-top">${list.slice(0,5).map((a,i)=>card(a,i?'s':'l')).join('')}</div>${list.length>5?`<div class="sec" style="padding-top:40px">${secHead('More','','')}<div class="g4">${list.slice(5).map(a=>card(a,'s')).join('')}</div></div>`:''}`:'<div class="empty"><b>Nothing filed here yet.</b>Check the archive for related files.</div>'}</div>`}
function pageMarkets(){setMeta('Markets — Market Files','Market board: equities, rates, commodities, FX and crypto.');return `<div class="wrap page-in" style="--dc:var(--up)"><header class="ph"><h1>Markets</h1><p>Wall Street and global markets in one view: indices, sectors, Treasuries, world exchanges, currencies and yields.</p></header>${boardTabs(true)}</div>`}

function fuSig(){const g=id=>INSTR.find(q=>q.id===id);const p=q=>q.na?null:(q.v-q.prev)/q.prev*100;const es=g('ES1'),v=p(es);const s=session('fu');
  const row=id=>{const q=g(id),x=p(q);return `<div class="fs-r"><span>${esc(q.name.replace('E-mini ',''))}</span><b class="mono ${x==null?'flat':x>=0?'up':'dn'}">${x==null?'—':(x>=0?'+':'')+x.toFixed(2)+'%'}</b></div>`};
  return `<div class="fs"><p class="mono dim">S&amp;P 500 FUTURES VS. PRIOR SETTLE</p><p class="fs-big mono ${v==null?'flat':v>=0?'up':'dn'}">${v==null?'—':(v>=0?'+':'')+v.toFixed(2)+'%'}</p><p class="fs-t">${v==null?'Waiting for futures data.':`Futures point to a ${Math.abs(v)<.05?'flat':v>0?'higher':'lower'} open for U.S. stocks.`}</p>${['NQ1','YM1','RTY1','ZN1'].map(row).join('')}<p class="mono dim fs-s">${s.t}</p></div>`}
/* futures page */
/* ---------- Futures hub (Stage 1 pilot of the Market Files learning hubs) ----------
   HUB CONTENT RULES: every date, number and claim below is checked against a primary source
   (listed under each tab). Educational only — never a recommendation of a broker or trade. */
const HUB_CHECKED='Oct 12, 2026';
const hubSrc=l=>`<p class="hub-src">Sources: ${l.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${t}</a>`).join(' · ')} · checked ${HUB_CHECKED}</p>`;
const hubCards=c=>`<div class="hub-g">${c.map(([t,b])=>`<div class="hub-c" data-holo><h3>${t}</h3>${b}</div>`).join('')}</div>`;
const FUT_RISK='Futures trading involves substantial risk of loss. You can lose your entire deposit and possibly more. Market Files is a news and media company; this is education, not financial advice.';
const FUT_HISTORY=[['1848-04-03','The Chicago Board of Trade is founded'],['1972-05-16','CME opens the International Monetary Market for currency futures'],['1977-08-22','CBOT launches U.S. Treasury bond futures'],['1982-04-21','S&P 500 futures begin trading at CME'],['1983-03-30','NYMEX launches crude oil futures'],['1992-06-25','CME Globex electronic trading goes live'],['1997-09-09','The E-mini S&P 500 launches'],['2007-07-12','CME and CBOT complete their merger'],['2017-12-17','CME launches bitcoin futures']];
/* Year-only milestones, each confirmed on CME Group's own pages (see Sources on the History tab). */
const FUT_YEARS=[['1865','CBOT introduces standardized futures contracts, after an initial period of trading forward contracts'],['1975','GNMA mortgage-backed futures are introduced, an early interest-rate contract'],['1981','Cash-settled Eurodollar futures begin: settled in cash rather than by delivery'],['1982','Options on futures are introduced, the same year S&P 500 futures launch'],['1990','Natural gas futures are introduced']];
function futHistoryHTML(){const all=[...FUT_HISTORY.map(([d,h])=>({y:d.slice(0,4),d,h})),...FUT_YEARS.map(([y,h])=>({y,h}))].sort((a,b)=>a.y===b.y?(a.d?1:0)-(b.d?1:0):a.y-b.y);
  return `<div class="otd-res" style="border:1px solid var(--line)">${all.map(e=>e.d?`<a class="ev" href="#/day/${e.d}"><span class="ev-y">${e.y}</span><div><h3>${esc(e.h)}</h3><div class="meta"><span>${fmtISO(e.d)}</span></div></div><span class="stamp review">In review</span></a>`:`<div class="ev"><span class="ev-y">${e.y}</span><div><h3>${esc(e.h)}</h3><div class="meta"><span>Year confirmed on CME Group’s pages</span></div></div><span class="stamp verified">Sourced</span></div>`).join('')}</div>`}
function futuresPricesHTML(){
  const t=`<table class="crt fut-t${window.MF_TV_FUT?' tv':''}"><thead><tr><th>Contract</th><th>Exchange</th><th>Contract size</th><th>Last</th><th>Change</th><th>Trend</th><th><span class="sr">Links</span></th></tr></thead><tbody>${FUGROUPS.map(g=>{const rows=INSTR.filter(q=>q.fut&&q.fg===g.id);return `<tr class="fut-g"><td colspan="7">${g.name}</td></tr>`+rows.map(q=>{const c=chg(q);return `<tr class="cr-row" data-id="${q.id}" ${rowAttr(q)}><td><b>${esc(q.name)}</b> <span class="mono dim">${q.id.replace(/1$/,'')}</span></td><td class="mono">${q.fx}</td><td class="mono dim">${q.size}</td><td class="mono" data-f="v">${fmtV(q)}</td><td class="mono c ${c.cls}" data-f="c">${c.arrow} ${c.txt}</td><td>${spark(q)}</td><td class="lks"><a href="${tvUrl(q.id)}" target="_blank" rel="noopener">TV ↗</a></td></tr>`}).join('')}).join('')}</tbody></table>`;
  return `${window.MF_TV_FUT?tvFuturesBlock(true):stripTiles(DESK_INST.futures)}<div style="height:28px"></div>
  ${heatGrid(INSTR.filter(q=>q.fut),'Futures heat map · front month')}<div style="height:20px"></div>
  <section class="pnl" data-holo><div class="pnl-h"><h3>All contracts · front month</h3><span class="sess">Data: ${Feed.name}</span></div><div class="tscroll">${t}</div></section>
  <p class="pv">Contract sizes are standard exchange specifications; confirm details on the exchange’s contract page before trading. Click any tile or row for its chart.</p>`}
function futuresLearnHTML(){return hubCards([
  ['What a futures contract is','<p>A futures contract is a standardized agreement to buy or sell a set quantity of something (an index, a barrel of oil, an ounce of gold, a bushel of corn) at a price agreed today, with settlement on a set future date. Contracts trade on regulated exchanges, and a clearinghouse stands between every buyer and seller.</p>'],
  ['Who trades them','<p><b>Hedgers</b> such as farmers, airlines, miners and funds use futures to lock in prices and reduce risk. <b>Speculators</b> take on that price risk hoping to profit from moves. Both are needed for a liquid market.</p>'],
  ['Anatomy of a contract','<ul><li><b>Underlying:</b> what the contract tracks</li><li><b>Contract size:</b> how much of it one contract covers</li><li><b>Tick:</b> the smallest price move, and what it is worth in dollars</li><li><b>Expiration:</b> the month the contract ends</li><li><b>Settlement:</b> cash, or physical delivery</li></ul>'],
  ['Worked example: E-mini S&P 500','<p>One E-mini S&amp;P 500 contract is worth $50 times the index. The smallest move is 0.25 index points, which equals $12.50. If the index is at 6,500, one contract controls $325,000 of exposure. Always confirm the live specifications on the CME Group contract page.</p>'],
  ['Margin and leverage','<p>Margin is a good-faith deposit, much smaller than the contract’s full value. That leverage magnifies gains <i>and</i> losses. Under the standard industry risk disclosure, you can lose your entire deposit and possibly more; your broker can demand more margin on short notice, close your position if you do not meet it, and you owe any shortfall. Price limits can also make it hard to exit.</p>'],
  ['Daily settlement','<p>Futures accounts are marked to market every day: gains are credited and losses are debited to your account at the daily settlement price, so a losing position can trigger a margin call before you ever close it.</p>'],
  ['Expiration and rolling','<p>Every contract expires. The nearest month is called the front month, and the prices on this page are front-month prices. Traders who do not want to settle either close the position or “roll” it into the next month before expiry. Most speculators never intend to take delivery.</p>'],
  ['Contango and backwardation','<p>When later-dated futures cost more than the current price, the market is in <b>contango</b>. When they cost less, it is in <b>backwardation</b>. The shape of the curve shows how the market is pricing storage, supply and demand over time.</p>'],
  ['Why futures move overnight','<p>Equity-index futures trade nearly 24 hours a day on weekdays, so they react to overseas news and economic data before the stock market opens. That is why “futures are up” or “futures are down” headlines come out before the bell.</p>']
])+`<p class="pv">${FUT_RISK}</p>`+hubSrc([['FIA risk disclosure (hosted by CME Group)','https://www.cmegroup.com/fcm/files/fia-risk-disclosure.pdf'],['Schwab: stock index futures tick values','https://www.schwab.com.sg/story/stock-index-futures-tick-values'],['CME Group education','https://www.cmegroup.com/education.html']])}
function futuresTradeHTML(){return `<section class="pnl" data-holo><div class="pnl-h"><h3>How people get started with futures</h3><span class="sess mono">A learning path, not a recommendation</span></div><div class="hub-c"><ol class="hub-ol">
  <li><b>Practice with no money first.</b> CME Group offers a trading simulator with a free practice account where you can study charts, add indicators and test strategies.</li>
  <li><b>Pick one market and learn its contract.</b> Read the exchange’s contract page: size, tick value, trading hours, expiry month and settlement method.</li>
  <li><b>Choose a registered broker.</b> In the U.S., check the firm and the individual on the National Futures Association’s BASIC database before opening an account (see “Where to trade”).</li>
  <li><b>Understand margin before you fund the account.</b> Know the initial and maintenance requirements and what triggers a margin call.</li>
  <li><b>Learn the basic order types.</b> A market order fills at the best available price now; a limit order fills only at your price or better; a stop order becomes a market order once a price is touched. Fast markets can fill away from your price (slippage).</li>
  <li><b>Write a risk plan before the first trade.</b> Decide the most you will lose on one trade and in one day, how large a position you can afford, and where you exit if you are wrong.</li>
  <li><b>Track expiry dates.</b> Know when your contract expires and whether you will close or roll.</li></ol></div></section>
  <div style="height:20px"></div>`+hubCards([
  ['Over-leveraging','<p>Using too much of your account on one contract is the fastest way to a margin call. Size positions so a normal move against you is survivable.</p>'],
  ['Trading with no exit plan','<p>Deciding where you are wrong <i>after</i> the trade moves against you usually means holding a loser too long.</p>'],
  ['Ignoring contract size','<p>One point in the E-mini S&amp;P is worth $50; one point in another contract can be worth far more or less. Always know your dollar value per tick.</p>'],
  ['Forgetting expiry','<p>Holding past the last trading day can mean cash settlement or physical delivery you did not intend. Put expiry dates on your calendar.</p>']
])+`<p class="pv">${FUT_RISK}</p>`+hubSrc([['CME Group Trading Simulator and education','https://www.cmegroup.com/education.html'],['FIA risk disclosure (hosted by CME Group)','https://www.cmegroup.com/fcm/files/fia-risk-disclosure.pdf'],['NFA BASIC (registration lookup)','https://www.nfa.futures.org/basicnet/']])}
function futuresWhereHTML(){return hubCards([
  ['CME Group','<p>A major U.S. futures exchange group. It operates four exchanges: <b>CME</b> (equity indexes, currencies, livestock, crypto), <b>CBOT</b> (Treasuries, grains, equity indexes), <b>NYMEX</b> (energy, platinum) and <b>COMEX</b> (gold, silver, copper), as shown in the Exchange column of our contracts table.</p>'],
  ['ICE Futures U.S.','<p>A U.S. futures exchange registered with the CFTC as a Designated Contract Market. It lists agriculture (soft commodities), energy such as Henry Hub natural gas and power, equity-index and currency futures, and precious metals.</p>'],
  ['Cboe','<p>Lists VIX futures, the contract many traders use to take a view on expected stock-market volatility.</p>'],
  ['CFTC: the regulator','<p>The Commodity Futures Trading Commission regulates futures markets in the United States. Its website has investor-protection material and ways to report fraud.</p>'],
  ['NFA and BASIC: check before you open an account','<p>The National Futures Association is the industry’s self-regulatory body. Its <b>BASIC</b> database (Background Affiliation Status Information Center) lets you look up a firm or individual’s registration and regulatory history. Never open an account with a firm you cannot find there.</p>'],
  ['How to compare brokers','<ul><li>Registered with the CFTC and an NFA member</li><li>Clear commission, platform and data fees</li><li>Margin requirements and what happens at a margin call</li><li>Customer funds held in segregated accounts</li><li>Platform quality, support and a clean complaint history in BASIC</li></ul><p>Market Files does not rank or recommend brokers.</p>'],
  ['Outside the United States','<p>Futures rules, registered firms and available contracts differ by country. Check your own country’s financial regulator before opening an account.</p>']
])+`<p class="pv">${FUT_RISK}</p>`+hubSrc([['ICE Futures U.S.','https://www.ice.com/futures-us'],['CME Group','https://www.cmegroup.com/'],['CFTC','https://www.cftc.gov/'],['NFA BASIC','https://www.nfa.futures.org/basicnet/']])}
function futuresChartHTML(){return hubCards([
  ['Candlesticks','<p>Each candle shows one time period: the open, high, low and close. A green (up) candle closed above where it opened; a red (down) candle closed below. Long wicks show prices that were rejected.</p>'],
  ['Trend lines','<p>Draw a line under a series of rising lows (an uptrend) or over a series of falling highs (a downtrend). A trend line the price keeps respecting is more meaningful; a break of it is a warning, not a guarantee.</p>'],
  ['Support and resistance','<p>Support is a price area where buyers have stepped in before; resistance is where sellers have. Prices often pause or reverse near these levels, and a broken resistance can turn into support.</p>'],
  ['Moving averages','<p>A moving average smooths price by averaging the last N periods. Price above a rising average suggests an uptrend; below a falling one suggests a downtrend. They lag, so they confirm trends rather than predict them.</p>'],
  ['Volume','<p>Volume is how many contracts traded. A move on rising volume has more participation behind it than the same move on thin volume.</p>'],
  ['Timeframes','<p>Check a higher timeframe (daily) for the trend and a lower one (hourly) for entries. A level on the daily chart usually matters more than one on a five-minute chart.</p>'],
  ['Keep it simple','<p>Beginners do better with a clean chart (price, volume, one or two tools) than a screen full of indicators. No chart pattern works every time, so pair any setup with a risk plan.</p>']
])+`<section class="pnl" data-holo style="margin-top:20px"><div class="pnl-h"><h3>Recommended free-to-start tutorials</h3><span class="sess mono">External sites</span></div><div class="hub-c"><ul class="hub-ol">
  <li><a href="https://www.cmegroup.com/education.html" target="_blank" rel="noopener"><b>CME Group Education ↗</b></a>: self-paced futures courses, a glossary, and a trading simulator with a free practice account.</li>
  <li><a href="https://school.stockcharts.com/doku.php?id=chart_analysis" target="_blank" rel="noopener"><b>StockCharts ChartSchool: Chart Analysis ↗</b></a>: articles on what charts are, support and resistance, trend lines, gaps, chart patterns and candlestick charts.</li></ul></div></section>
  <p class="pv">${FUT_RISK}</p>`+hubSrc([['CME Group education','https://www.cmegroup.com/education.html'],['StockCharts ChartSchool','https://school.stockcharts.com/doku.php?id=chart_analysis']])}
function futuresHistoryHTML(){return `<section>${secHead('How the futures market was built','From Chicago grain trading to bitcoin futures.','')}${futHistoryHTML()}</section>`+hubSrc([['CME Group timeline of product launches','https://www.cmegroup.com/stories/_files/longdesc/timeline.html'],['CME Group: history of futures exchanges','https://www.cmegroup.com/education/courses/introduction-to-futures/midwest-grain-trade-history-of-futures-exchanges.html']])}
function pageFutures(){setMeta('Futures — Market Files','The futures hub: live front-month prices, a heat map, how futures work, how to trade them, where to trade and beginner charting tutorials.');
  const tabs=tabsHTML('fh',[['px','Prices &amp; heat map',futuresPricesHTML()],['ln','Learn the basics',futuresLearnHTML()],['tr','How to trade',futuresTradeHTML()],['wh','Where to trade',futuresWhereHTML()],['ch','Charting basics',futuresChartHTML()],['hs','History',futuresHistoryHTML()]],'tabs-main');
  return `<div class="wrap page-in" style="--dc:#C9A55C"><header class="ph serif">${hudEyebrow('MARKET FILES GUIDE')}<h1 class="holo holo-gold">Futures</h1><p>The futures market is one of the largest and most important in the world: equity indexes, Treasuries, energy, metals, agriculture, currencies, crypto and volatility, trading nearly around the clock. Prices, a heat map, and everything you need to understand it.</p><div class="sec-a">${sessHTML('fu')}<span class="mono dim">CME Globex: Sunday–Friday, 6:00 p.m.–5:00 p.m. ET with a daily one-hour break</span></div></header>
  ${tabs}
  <nav class="hub-rel" aria-label="Related"><span class="mono dim">RELATED</span><a href="#/dashboard">Live dashboard <i aria-hidden="true">→</i></a><a href="#/crypto">Bitcoin and crypto prices <i aria-hidden="true">→</i></a></nav></div>`}


/* ---------- Learning hubs: Crypto, Gold & Silver, Stocks, Global, Learn ----------
   Content comes from the 2026-10-12 research pack. Only items confirmed against a source are shown;
   anything the researcher could not confirm is deliberately left out or marked "not verified". */
const HD={"cryptoLearn": [["Blockchain", "A blockchain links blocks of records cryptographically. Bitcoin uses a distributed proof-of-work history to address double spending without a central payment processor.", [["Bitcoin white paper", "https://bitcoin.org/bitcoin.pdf"]]], ["Proof of work", "Bitcoin miners perform computational work to propose blocks; other nodes check the blocks against the network rules.", [["Bitcoin white paper", "https://bitcoin.org/bitcoin.pdf"]]], ["Proof of stake", "Ethereum replaced proof-of-work consensus with proof of stake at the Merge on September 15, 2022. Validators stake ETH rather than compete through mining.", [["ethereum.org: the Merge", "https://ethereum.org/roadmap/merge/"]]], ["Ethereum", "Ethereum supports programmable smart contracts and applications. ETH is its native asset, distinct from tokens created by applications.", [["ethereum.org: what is Ethereum", "https://ethereum.org/what-is-ethereum/"]]], ["Stablecoins", "Stablecoins aim to track a reference value, often a currency. The peg and any redemption mechanism introduce risks rather than eliminating them.", [["ethereum.org: stablecoins", "https://ethereum.org/stablecoins/"]]], ["Keys and recovery phrases", "A wallet manages access credentials rather than storing the coins themselves. Private keys authorize transactions, and recovery phrases can restore access. Anyone who obtains those secrets may obtain control.", [["SEC Investor.gov: crypto asset custody basics", "https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/crypto-asset-custody-basics-retail-investors-investor-bulletin-0"]]], ["Gas", "Gas measures computational work on Ethereum. A transaction fee combines the gas used with its price.", [["ethereum.org glossary", "https://ethereum.org/glossary/"]]], ["DeFi", "Decentralized finance uses blockchain applications for activities such as swaps and lending. Smart contracts and their interfaces can introduce technical and governance risks.", [["ethereum.org: DeFi", "https://ethereum.org/defi/"]]], ["NFTs", "Non-fungible tokens identify distinct tokens. A token record does not by itself establish every legal right to an associated image or other asset.", [["ethereum.org: NFTs", "https://ethereum.org/nft/"]]], ["Layer 2", "Ethereum layer-2 systems process activity outside the base chain while deriving security from Ethereum. The specific design and withdrawal arrangements matter.", [["ethereum.org: layer 2", "https://ethereum.org/layer-2/"]]]], "cryptoBtc": [["The white paper", "The paper is titled “Bitcoin: A Peer-to-Peer Electronic Cash System” and names Satoshi Nakamoto as author. The surviving Cryptography mailing-list announcement is dated October 31, 2008 and links to the paper. That establishes the public announcement, not the author’s real-world identity.", [["Bitcoin white paper", "https://bitcoin.org/bitcoin.pdf"], ["Mailing-list announcement", "https://www.metzdowd.com/pipermail/cryptography/2008-October/014810.html"]]], ["Genesis block", "Bitcoin Core encodes the main-network genesis timestamp as 1231006505, which is January 3, 2009, 18:15:05 UTC. This is the block’s recorded timestamp, not independent evidence of the exact moment a person created it.", [["Bitcoin Core source", "https://github.com/bitcoin/bitcoin/blob/master/src/kernel/chainparams.cpp"]]], ["Supply schedule", "Under Bitcoin’s present issuance rules, the block subsidy halves every 210,000 blocks, and total issuance approaches the commonly stated 21 million BTC limit. Lost keys do not increase that limit.", [["bitcoin.org: halving", "https://bitcoin.org/en/halving"]]], ["2012 halving", "November 28, 2012: block 210,000 reduced the block subsidy from 50 to 25 BTC.", [["bitcoin.org: halving", "https://bitcoin.org/en/halving"]]], ["2016 halving", "July 9, 2016: block 420,000 reduced the subsidy from 25 to 12.5 BTC.", [["bitcoin.org: halving", "https://bitcoin.org/en/halving"]]], ["2020 halving", "May 11, 2020: block 630,000 reduced the subsidy from 12.5 to 6.25 BTC.", [["bitcoin.org: halving", "https://bitcoin.org/en/halving"]]], ["2024 halving", "April 20, 2024 (UTC): block 840,000 reduced the subsidy from 6.25 to 3.125 BTC. In US Eastern time the event fell on April 19. The subsidy is newly issued bitcoin; a miner’s total block revenue can also include transaction fees.", [["bitcoin.org: halving", "https://bitcoin.org/en/halving"]]]], "walletIntro": [["Hot, cold, self-custody and third-party custody", "Hot wallets are connected to the internet; cold storage keeps signing keys offline. Self-custody places key management with the user, while third-party custody adds dependence on the custodian and its legal arrangements.", [["SEC Investor.gov: crypto asset custody basics", "https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/crypto-asset-custody-basics-retail-investors-investor-bulletin-0"]]], ["How to vet a wallet", "Check who controls the keys, what the recovery dependencies are, the exact publisher of the download, whether the code is available, and what the version-specific audit findings and fixes were. For third-party custody, check the legal entity, asset segregation, insurance exclusions and insolvency terms. A familiar brand name is not enough.", [["SEC Investor.gov: crypto asset custody basics", "https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/crypto-asset-custody-basics-retail-investors-investor-bulletin-0"]]], ["How to read the track records below", "Market Files does not rank or endorse wallets. Each entry lists only what was confirmed from the maker’s own pages or an audit report. A source-code repository or a security audit is not a financial-services licence. Where an item says it was not confirmed, that means “not established in our review,” never “no incidents.”", null]], "wallets": [["Ledger (hardware)", "Ledger describes a hardware-signing model and publishes the Ledger Wallet application’s source, while portions of its device operating system remain closed. Audit firm, date and licence details for a specific product version were not confirmed.", [["Ledger: is Ledger open source?", "https://www.ledger.com/academy/topics/ledgersolutions/is-ledger-open-source"]]], ["Ledger incident, December 2023", "Ledger’s own report describes the December 14, 2023 compromise of its Connect Kit, a JavaScript integration used by applications. That report is not proof that private keys were extracted from hardware devices.", [["Ledger security incident report", "https://www.ledger.com/blog/security-incident-report"]]], ["Trezor (hardware)", "Trezor publishes its firmware repository, so the code and its licences can be inspected. That confirms source availability. Model-specific custody details, audit reports and a dated incident assessment were not confirmed.", [["trezor-firmware on GitHub", "https://github.com/trezor/trezor-firmware"]]], ["COLDCARD (hardware)", "Coinkite publishes COLDCARD firmware and simulator code. Source availability is not the same as an unrestricted open-source licence. Its repository carries a seed-generation security advisory for the Mk3, so refer to the maker’s current advisory rather than assume any product is immune from vulnerabilities.", [["COLDCARD firmware", "https://github.com/Coldcard/firmware"], ["Coinkite advisory", "https://blog.coinkite.com/coldcard-mk3-seed-generation-warning/"]]], ["Blockstream Jade (hardware)", "Blockstream publishes Jade firmware, build instructions and licence files. That establishes public source availability. Model-specific audits, incident history and third-party service dependencies were not confirmed.", [["Jade on GitHub", "https://github.com/Blockstream/Jade"], ["Blockstream Jade", "https://blockstream.com/jade/"]]], ["Keystone (hardware)", "Keystone publishes its Keystone 3 firmware. Least Authority’s final audit, dated March 20, 2025, examined specified Zcash integration code and signing and QR-protocol components. That is a defined software scope, not a certification of every supported chain, physical component or later firmware version.", [["Keystone 3 firmware", "https://github.com/KeystoneHQ/keystone3-firmware"], ["Least Authority audit (PDF)", "https://leastauthority.com/wp-content/uploads/2025/03/Least-Authority-ZCG-Keystone-Hardware-Wallet-Final-Audit-Report.pdf"]]], ["MetaMask (software)", "The MetaMask browser-extension source is publicly available in its official repository; check the current licence before describing reuse rights. Exact-version custody and recovery options, audit coverage and incident history were not confirmed.", [["metamask-extension on GitHub", "https://github.com/MetaMask/metamask-extension"]]], ["Phantom (software)", "Phantom describes its wallet as self-custodial. Its homepage also advertises trading, perpetuals and prediction products. Complete source availability, audit firm and date, and incident history were not confirmed.", [["Phantom", "https://phantom.com/"]]], ["Trust Wallet (software)", "Trust Wallet describes a self-custody mobile and browser wallet, and Cure53 published a browser-extension security report in April 2023. That report covers one extension review, not all present releases. Whole-application open-source status and incident history were not confirmed.", [["Trust Wallet", "https://trustwallet.com/"], ["Cure53 report (PDF)", "https://trustwallet.com/assets/files/cure53_tw_browser_extension_04.2023.pdf"]]], ["Exodus (software)", "Exodus states that parts of its code are open source while other parts are not, so the whole application should not be called fully open source. Version-specific audit coverage, custody and recovery details and dated incidents were not confirmed.", [["Exodus: is Exodus open source?", "https://www.exodus.com/support/en/articles/8598678-is-exodus-open-source"]]], ["Coinbase Wallet (software)", "The opened Coinbase Wallet page establishes a separate wallet-branded product, but not enough detail to verify every custody or recovery configuration. A Coinbase exchange licence does not transfer to the wallet. Current product naming, source status, audits and incident history were not confirmed.", [["Coinbase Wallet", "https://wallet.coinbase.com/"]]], ["Rabby (software)", "RabbyHub publishes the Rabby extension repository for Ethereum and EVM-chain use. Source is available, but a named, dated audit report, current-version custody details and incident history were not confirmed.", [["Rabby on GitHub", "https://github.com/RabbyHub/Rabby"]]]], "exchIntro": [["How to read this tab", "“Registered,” “licensed,” “authorised” and “in-principle approval” are different statuses. Check the exact legal entity, official domain, permitted activity, territory and current restrictions directly in the regulator’s record. The examples below are non-exhaustive snapshots from regulator pages on October 12, 2026. They are not recommendations and not permission to serve every customer. Countries with no names listed are ones where we could not read the register; use the official link or search the regulator’s site.", null]], "exch": [["United States", "The New York Department of Financial Services list shows Coinbase, Inc. with Virtual Currency and Money Transmitter Licenses granted in January 2017, and Gemini Trust Company, LLC with a Limited Purpose Trust Charter granted in October 2015. These are New York entries, not nationwide authorisation.", [["NYDFS: virtual currency businesses", "https://www.dfs.ny.gov/apps_and_licensing/virtual_currency_businesses"]]], ["Canada", "The Canadian Securities Administrators’ authorised-platform list includes Coinbase Canada Inc., Payward Canada Inc. (Kraken) and Foris DAX CAN ULC (Crypto.com), with linked regulatory decisions. Match the entity and province or territory and read the decision’s conditions. The list includes firms with restrictions, so a listed name alone is not enough.", [["CSA: authorised crypto platforms", "https://www.securities-administrators.ca/crypto-platforms-regulation-and-enforcement-actions/crypto-platforms-authorized-to-do-business-with-canadians/"]]], ["United Kingdom", "The Financial Conduct Authority says in-scope cryptoasset businesses must register under the money-laundering regulations, and that the new FSMA cryptoasset regime begins October 25, 2027. We could not verify individual register entries, so no exchange is listed as authorised here.", [["FCA: who needs to register", "https://www.fca.org.uk/firms/cryptoassets/who-needs-register"], ["FCA: registration under the MLRs", "https://www.fca.org.uk/firms/new-regime-cryptoasset-regulation/registration-under-mlrs-ahead-new-fsma-regime"]]], ["European Union (MiCA)", "ESMA provides the interim MiCA register, including crypto-asset service providers, and identifies the national competent authorities. Check a provider’s service scope, home authority and any withdrawal fields. We could not retrieve the downloadable firm list, so no individual names are given here.", [["ESMA: MiCA", "https://www.esma.europa.eu/esmas-activities/digital-finance-and-innovation/markets-crypto-assets-regulation-mica"]]], ["Germany and France", "We could not open the BaFin or AMF registers, so no entries are listed. Check the national regulator together with the ESMA MiCA record for the exact legal entity and service scope. An old registration is not the same as current authorisation.", null], ["Japan", "The Financial Services Agency’s list dated September 1, 2026 includes bitFlyer, Inc. (Kanto No. 00003) and bitbank, inc. (Kanto No. 00004), both registered September 29, 2017. Match the registration number, corporate identity and permitted assets. The document does not endorse the assets listed.", [["FSA: registered crypto-asset exchange operators (PDF)", "https://www.fsa.go.jp/en/regulated/licensed/en_kasoutuka.pdf"]]], ["South Korea", "The Korea Financial Intelligence Unit and Financial Supervisory Service released a survey on October 1, 2026 of 26 registered virtual asset service providers covering January through June 2026. That survey is not a live firm register, so no names are given. Check the current register directly.", [["FSC press release", "https://www.fsc.go.kr/eng/pr010101/87833"]]], ["Singapore", "The Monetary Authority of Singapore’s directory shows COINBASE SINGAPORE PTE. LTD. as a Major Payment Institution with Digital Payment Token Service and Cross-border Money Transfer Service. Match the legal entity and listed activity. The record we read did not give a licence number or grant date.", [["MAS: Coinbase Singapore record", "https://eservices.mas.gov.sg/fid/institution/detail/235467-COINBASE-SINGAPORE-PTE-LTD"]]], ["Australia", "AUSTRAC announced a public virtual-asset service-provider register on June 30, 2026, replacing the old digital-currency-exchange terminology. The register returned no usable firm rows when we checked, so no names are given. AML registration is not an investment guarantee.", [["AUSTRAC announcement", "https://www.austrac.gov.au/news-and-media/article/virtual-asset-service-provider-register-goes-public"]]], ["India", "India’s Financial Intelligence Unit lists VDA anti-money-laundering guidance updated January 8, 2026 and a registration circular dated September 15, 2025. We could not verify a current exchange-by-exchange official register, so no names are given.", [["FIU-IND downloads", "https://fiuindia.gov.in/files/downloads/downloads.html"]]], ["Brazil", "We could not read the Banco Central page for Resolution BCB 520, so its framework, authorisation transition and register are not summarised here. Check the central bank directly.", null], ["United Arab Emirates (Dubai)", "The Dubai Virtual Assets Regulatory Authority register lists Rain MENA FZE as Active, VASP Licence VL/26/10/001, issued October 5, 2026, for Exchange and Broker-Dealer Services. VARA says in-principle approval does not permit operations. Broader UAE, DIFC and ADGM permissions are not established by this entry.", [["VARA public register", "https://www.vara.ae/en/licenses-and-register/public-register/"]]]], "howto": [["Set up and back up a wallet", "Identify the official publisher, understand the recovery method and keep the recovery phrase private. Practise with fictional examples. Never type real wallet secrets into a website, a lesson or a chat.", [["SEC Investor.gov: crypto asset custody basics", "https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/crypto-asset-custody-basics-retail-investors-investor-bulletin-0"]]], ["Send, receive and test", "A Bitcoin address identifies a payment destination, and confirmations indicate that a transaction has been included in the blockchain. Compare the complete destination address and the intended network, understand the fee, and use a small test transfer first. A test does not prove a recipient is trustworthy.", [["bitcoin.org vocabulary", "https://bitcoin.org/en/vocabulary"]]], ["Open an exchange account, buy and sell", "Interfaces, eligibility, identity documents and order flows differ by legal entity and country, so there is no single click-by-click guide. Learn the concepts, then confirm the exchange’s legal entity and permissions in your own country’s regulator record (see the Exchanges tab).", [["FCA: who needs to register", "https://www.fca.org.uk/firms/cryptoassets/who-needs-register"]]], ["Keep records for taxes", "In the United States, crypto-to-crypto transactions can matter for tax reporting, not only conversions into bank money. Keep dates, units, values and cost basis. The links below are official reference pages, not tax advice.", [["IRS: digital assets", "https://www.irs.gov/filing/digital-assets"]]]], "tax": [["United States — IRS", "https://www.irs.gov/filing/digital-assets"], ["United Kingdom — HMRC", "https://www.gov.uk/government/collections/cryptoassets"], ["France — DGFiP", "https://www.impots.gouv.fr/particulier"], ["Japan — National Tax Agency", "https://www.nta.go.jp/english/"], ["South Korea — National Tax Service", "https://www.nts.go.kr/english/main.do"], ["India — Income Tax Department", "https://www.incometax.gov.in/iec/foportal/"], ["Brazil — Receita Federal", "https://www.gov.br/receitafederal/pt-br"], ["UAE — Federal Tax Authority", "https://tax.gov.ae/en/"]], "termsBtc": [["Address", "Payment destination identifier"], ["Bitcoin", "Peer-to-peer electronic payment network"], ["BTC", "Common bitcoin unit abbreviation"], ["Bit", "One millionth of a bitcoin"], ["Block", "Grouped transactions linked into the chain"], ["Blockchain", "Shared, ordered history of blocks"], ["Confirmation", "Transaction inclusion followed by additional blocks"], ["Cryptography", "Mathematical techniques securing information"], ["Double spend", "Attempt to spend the same funds twice"], ["Hash rate", "Mining computations performed per second"], ["Mining", "Proof-of-work block production"], ["P2P", "Peer-to-peer network architecture"], ["Private key", "Secret used to authorize spending"], ["Signature", "Cryptographic evidence of authorization"], ["Wallet", "Software or hardware managing payment access"]], "termsEth": [["Account", "Ethereum state associated with an address"], ["Block explorer", "Interface for inspecting blockchain records"], ["Consensus", "Agreement on a valid chain state"], ["dapp", "Application using decentralized blockchain components"], ["DAO", "Organization coordinated through on-chain rules"], ["Ether", "Ethereum’s native asset"], ["EVM", "Ethereum Virtual Machine"], ["Finality", "Consensus assurance against reversing finalized blocks"], ["Fork", "Divergence in protocol rules or chain history"], ["Gas", "Unit measuring computation"], ["Gwei", "One billion wei"], ["Hash", "Fixed-length cryptographic digest"], ["Mainnet", "Primary live blockchain network"], ["Node", "Computer participating in a blockchain network"], ["Nonce", "Counter preventing account transaction replay"], ["Oracle", "Mechanism supplying external information on-chain"], ["Public key", "Public cryptographic counterpart to a private key"], ["Rollup", "Execution system posting commitments to a base chain"], ["Slashing", "Penalty for certain validator misconduct"], ["Smart contract", "Program executed under blockchain rules"], ["Staking", "Committing assets to proof-of-stake validation"], ["Testnet", "Network used for testing"], ["Token", "Asset represented by blockchain rules"], ["Transaction", "Signed instruction changing blockchain state"], ["Validator", "Participant proposing or attesting to blocks"], ["Wei", "Smallest denomination of ether"]], "news": [["Regulator and law-enforcement releases", "Use original FCA, SEC/Investor.gov, FTC and DOJ material to distinguish rules, allegations, settlements and judgments. These are primary accounts of each institution’s own actions, not guarantees that every disputed allegation has been proven.", [["FCA", "https://www.fca.org.uk/firms/cryptoassets/who-needs-register"], ["FTC: Voyager", "https://www.ftc.gov/legal-library/browse/cases-proceedings/2223149-voyager-digital-llc-et-al-ftc-v"], ["DOJ: Kwon", "https://www.justice.gov/usao-sdny/united-states-v-kwon-23-cr-151-pae-terraform-labs-fraud"]]], ["Project documentation and code", "Bitcoin Core’s source and Ethereum’s documentation provide direct evidence of published implementation and protocol design. Separate documentation from independent security assessment, and attribute claims to whoever made them.", [["Bitcoin Core source", "https://github.com/bitcoin/bitcoin/blob/master/src/kernel/chainparams.cpp"], ["ethereum.org: the Merge", "https://ethereum.org/roadmap/merge/"]]], ["Terra criminal case", "The Department of Justice’s case page records Do Kwon’s sentence of 15 years on December 11, 2025. It is a dated case outcome, not a claim about creditor recoveries.", [["DOJ case page", "https://www.justice.gov/usao-sdny/united-states-v-kwon-23-cr-151-pae-terraform-labs-fraud"]]], ["Celsius founders and the FTC", "The Federal Trade Commission’s July 2026 release reports orders requiring Celsius founders to pay a combined $16.5 million to resolve its charges. Keep this civil action separate from Alexander Mashinsky’s criminal sentence and bankruptcy recoveries.", [["FTC press release", "https://www.ftc.gov/news-events/news/press-releases/2026/07/founders-celsius-network-ordered-pay-165-million-resolve-ftc-charges"]]], ["Australia’s public register", "AUSTRAC’s public register launch on June 30, 2026 changes how readers can check a provider. The announcement is verified; individual live entries were not retrieved.", [["AUSTRAC", "https://www.austrac.gov.au/news-and-media/article/virtual-asset-service-provider-register-goes-public"]]], ["A note on news channels", "Market Files does not rank news outlets or social channels. These are primary sources you can read directly. A full list of reputable outlets is still being reviewed and will be added when each one has been checked.", null]], "cryptoRisks": [["Mt. Gox", "The Department of Justice’s June 9, 2023 announcement alleges the laundering of approximately 647,000 bitcoin stolen from Mt. Gox and describes theft contributing to the exchange’s insolvency. Criminal charges are not convictions. The 2014 closure chronology and current repayments have not been verified here.", [["DOJ announcement", "https://www.justice.gov/usao-sdny/pr/russian-nationals-charged-hacking-one-cryptocurrency-exchange-and-illicitly-operating"]]], ["Celsius", "Celsius filed for bankruptcy on July 13, 2022. On May 8, 2025 the Department of Justice announced that founder Alexander Mashinsky was sentenced to 12 years for fraud and market manipulation. That sentence does not establish an individual customer’s recovery.", [["DOJ announcement", "https://www.justice.gov/usao-sdny/pr/founder-celsius-sentenced-12-years-fraud-and-market-manipulation"]]], ["Voyager", "The Federal Trade Commission’s case page describes misleading deposit-insurance claims and a settlement permanently banning Voyager from handling consumer assets. The platform’s 2022 bankruptcy and the later FTC case are separate events; the bankruptcy date and distributions were not verified here.", [["FTC case page", "https://www.ftc.gov/legal-library/browse/cases-proceedings/2223149-voyager-digital-llc-et-al-ftc-v"]]], ["FTX", "On March 28, 2024 the Department of Justice announced that Samuel Bankman-Fried was sentenced to 25 years for fraud following FTX’s collapse. This criminal outcome is distinct from the 2022 bankruptcy, appeals and creditor payments, whose current status was not checked.", [["DOJ announcement", "https://www.justice.gov/usao-sdny/pr/samuel-bankman-fried-sentenced-25-years-prison"]]], ["Terra/Luna", "The Department of Justice case concerns Terraform’s fraud and the collapse of its ecosystem. The case page records Do Kwon’s guilty plea and December 11, 2025 sentence. The exact May 2022 chronology and recovery percentages were not verified here.", [["DOJ case page", "https://www.justice.gov/usao-sdny/united-states-v-kwon-23-cr-151-pae-terraform-labs-fraud"]]], ["Bybit hack", "On February 26, 2025 the FBI attributed approximately $1.5 billion in virtual-asset theft from Bybit, on or about February 21, 2025, to North Korea’s TraderTraitor activity. Total recovered funds were not verified.", [["FBI alert", "https://www.fbi.gov/investigate/cyber/alerts/2025/north-korea-responsible-for-1-5-billion-bybit-hack"]]], ["QuadrigaCX", "We could not open the Ontario Securities Commission’s report, so the 2019 failure is not summarised here. Do not rely on simplified retellings; read the OSC findings.", [["OSC report", "https://www.osc.ca/quadrigacxreport/"]]]], "mLearn": [["Spot price vs. retail price", "Spot is a cash-market price for immediate metal delivery. A retail coin or bar price also reflects premiums and other costs, so compare like weight and purity, not just the headline price.", [["CFTC: metals, 10 things to know", "https://www.cftc.gov/LearnAndProtect/AdvisoriesAndArticles/Metals10Things.html"]]], ["Gold futures", "COMEX gold’s standard trading unit is 100 troy ounces, with a minimum price increment of $0.10 per ounce, or $10 per contract. Its delivery rules specify minimum 995 fineness and approved brands; delivery tolerances differ from the trading unit.", [["CME: COMEX gold rulebook (PDF)", "https://www.cmegroup.com/rulebook/COMEX/1a/113.pdf"]]], ["Silver futures", "COMEX silver’s standard trading unit is 5,000 troy ounces. The contract has specified delivery requirements, so a silver futures quote is not interchangeable with a local dealer’s retail bar offer.", [["CME: COMEX silver rulebook (PDF)", "https://www.cmegroup.com/rulebook/COMEX/1a/112.pdf"]]], ["LBMA benchmarks", "LBMA Gold Price auctions begin at 10:30 and 15:00 London time, and the Silver Price auction begins at noon, on publication days. ICE Benchmark Administration administers these benchmarks. A “fix” is not a continuously executable retail price.", [["LBMA prices", "https://www.lbma.org.uk/prices-and-data/lbma-precious-metal-prices"]]], ["The gold/silver ratio (a worked example)", "Divide the gold price by the silver price. If gold is $2,400 and silver is $30 per troy ounce, the ratio is 80. These are invented teaching prices, not current quotes. Keep currency, unit and observation time consistent.", [["CME: COMEX gold rulebook (PDF)", "https://www.cmegroup.com/rulebook/COMEX/1a/113.pdf"], ["CME: COMEX silver rulebook (PDF)", "https://www.cmegroup.com/rulebook/COMEX/1a/112.pdf"]]], ["Silver has more than one kind of demand", "The Silver Institute’s supply-and-demand material separates industrial fabrication from jewellery, silverware and investment demand. It is an industry source, not a government statistical agency.", [["Silver Institute", "https://silverinstitute.org/silver-supply-demand/"]]]], "mMoves": [["Gold supply and demand", "The World Gold Council’s Gold Demand Trends publishes sector and country data on demand alongside supply analysis. Note the report period and revisions, and remember WGC is an industry body.", [["WGC: Gold Demand Trends", "https://www.gold.org/goldhub/research/gold-demand-trends"]]], ["Central-bank holdings", "The WGC’s country reserve dataset is a reference for reported official gold holdings. Check its reporting dates and methodology. A country’s latest reported figure is not necessarily a same-day inventory.", [["WGC: gold reserves by country", "https://www.gold.org/goldhub/data/gold-reserves-by-country"]]], ["Positioning", "The CFTC’s Commitments of Traders reports describe reportable futures-market positioning by category. Positioning data are not a complete measure of physical-metal demand or a forecast of the next price move.", [["CFTC: Commitments of Traders", "https://www.cftc.gov/MarketReports/CommitmentsofTraders/index.htm"]]], ["Rates, currency and uncertainty", "The WGC’s 2020 analysis discusses uncertainty, low interest rates, dollar movements and investment demand. These are interacting influences, not a rule that gold must rise whenever inflation rises.", [["WGC: record-high analysis", "https://www.gold.org/goldhub/research/investment-update-gold-hits-record-high-sprint-or-marathon"]]]], "mOwn": [["Physical bullion", "Coins and bars involve ownership, delivery and storage arrangements as well as purchase and resale spreads. Get written terms rather than treating the spot price as the full cost of ownership.", [["CFTC: metals, 10 things to know", "https://www.cftc.gov/LearnAndProtect/AdvisoriesAndArticles/Metals10Things.html"]]], ["Exchange-traded exposure", "Metal-related exchange-traded products can provide price exposure without personal storage, but their legal structure, holdings, fees and redemption rules differ. A futures-based product and a physically backed product are not equivalent.", [["CFTC: metals, 10 things to know", "https://www.cftc.gov/LearnAndProtect/AdvisoriesAndArticles/Metals10Things.html"], ["CME: gold contract specs", "https://www.cmegroup.com/markets/metals/precious/gold.contractSpecs.html"]]], ["Mining-company shares", "A mining-company share is an equity interest in a business. It is not direct ownership of a specified amount of bullion, and the company’s operating and financing risks need separate research through its filings.", [["SEC Investor.gov: stocks", "https://www.investor.gov/introduction-investing/investing-basics/investment-products/stocks"]]], ["Mint products", "The US Mint’s collectible and investment-coin material distinguishes coin programs and formats. Use the issuer’s specifications to establish exactly what a product is, rather than assuming every gold-coloured or silver-coloured coin is bullion.", [["US Mint", "https://www.usmint.gov/learn/coins-and-medals/collectible-coins"]]]], "mTrade": [["A learning path for futures", "Learn the contract unit, tick value, margin, expiry and delivery obligations before looking at an order example. Practise with fictional cash and clearly labelled hypothetical prices. Margin is not the same as paying the full contract value.", [["CME: COMEX gold rulebook (PDF)", "https://www.cmegroup.com/rulebook/COMEX/1a/113.pdf"], ["CME: COMEX silver rulebook (PDF)", "https://www.cmegroup.com/rulebook/COMEX/1a/112.pdf"], ["CME: gold contract specs", "https://www.cmegroup.com/markets/metals/precious/gold.contractSpecs.html"]]], ["Know which price you are looking at", "Use separate labels for spot, futures contract month, benchmark and retail quote. Benchmark data access and redistribution can require a licence, so no page should imply freely reusable live LBMA data.", [["LBMA prices", "https://www.lbma.org.uk/prices-and-data/lbma-precious-metal-prices"]]]], "mWhere": [["Checking a dealer", "Check the dealer’s legal identity and any relevant registration, ask for a written buyback quote and all charges, and verify the storage provider independently. A business reputation listing is not proof of authorisation for a regulated service.", [["CFTC: metals, 10 things to know", "https://www.cftc.gov/LearnAndProtect/AdvisoriesAndArticles/Metals10Things.html"]]], ["Taxes", "Use your national tax authority as the starting point for bullion, coins, funds and futures. Treatment differs by country and product, and Market Files does not give tax conclusions.", null]], "mHist": [["1944: Bretton Woods", "The Bretton Woods conference established a monetary framework linking currencies to the dollar and the dollar to gold, alongside the IMF and World Bank arrangements. This is different from earlier domestic gold-standard arrangements.", [["Federal Reserve History: Bretton Woods", "https://www.federalreservehistory.org/essays/bretton-woods-created"]]], ["August 15, 1971: the Nixon shock", "President Nixon announced the suspension of dollar convertibility into gold along with other economic measures. It was a central break in the Bretton Woods arrangement, not the date every country stopped using every form of gold linkage.", [["Federal Reserve History: gold convertibility ends", "https://www.federalreservehistory.org/essays/gold-convertibility-ends"]]], ["1980, 2011 and 2020", "The World Gold Council’s 2020 record-price discussion compares that rally with 2011 and the inflation-adjusted 1980 peak. Exact peak prices are not given here because a consistent spot, fixing or futures series would be needed.", [["WGC analysis", "https://www.gold.org/goldhub/research/investment-update-gold-hits-record-high-sprint-or-marathon"]]]], "mRisk": [["Costs, counterfeits and custody", "Precious-metal fraud can involve inflated spreads or storage charges for metal that was never purchased. Independently verify what you own, where it is held and what insurance actually covers.", [["CFTC: metals, 10 things to know", "https://www.cftc.gov/LearnAndProtect/AdvisoriesAndArticles/Metals10Things.html"]]], ["Leverage and product mismatch", "Futures require attention to expiry and settlement. Exchange-traded exposure may carry fees and a structure that behaves differently from physical ownership. Gold does not protect against every kind of inflation or loss.", [["CME: COMEX gold rulebook (PDF)", "https://www.cmegroup.com/rulebook/COMEX/1a/113.pdf"], ["CME: gold contract specs", "https://www.cmegroup.com/markets/metals/precious/gold.contractSpecs.html"]]]], "sLearn": [["What a share is", "A stock represents an ownership interest in a company. Returns can include price changes and dividends, but ownership does not guarantee a dividend or protect against loss.", [["SEC Investor.gov: stocks", "https://www.investor.gov/introduction-investing/investing-basics/investment-products/stocks"]]], ["Indexes and the S&P 500", "S&P Dow Jones Indices publishes eligibility and maintenance rules for its US indexes, including float adjustment, liquidity and financial criteria. The S&P 500 is not simply an automatic list of whichever 500 stocks are largest that day.", [["S&P US indices methodology (PDF)", "https://www.spglobal.com/spdji/en/documents/methodologies/methodology-sp-us-indices.pdf"]]], ["ETFs, dividends and splits", "Use the SEC’s investor material to tell a fund share from an individual company share, and a cash distribution from a change in share count.", [["SEC Investor.gov: stocks", "https://www.investor.gov/introduction-investing/investing-basics/investment-products/stocks"], ["SEC Investor.gov: types of orders", "https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders"]]]], "sHow": [["Exchange hours", "The New York Stock Exchange’s core session is 9:30 a.m. to 4:00 p.m. Eastern time on normal trading days; its official calendar lists holidays and early closes. Other exchanges, venues and extended sessions have their own schedules.", [["NYSE: hours and calendars", "https://www.nyse.com/trade/hours-calendars"]]], ["T+1 settlement", "Since May 28, 2024, most US securities transactions settle one business day after the trade date. Execution and settlement are different events, and weekends and market holidays matter.", [["SEC Investor.gov: T+1 bulletin", "https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-bulletins/new-t1-settlement-cycle-what-investors-need-know-investor-bulletin"]]], ["Market, limit and stop orders", "A market order prioritises execution without fixing the price. A limit order sets a price boundary but may not execute. A stop order becomes a market order when triggered, so it does not guarantee the stop price.", [["SEC Investor.gov: types of orders", "https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders"]]], ["A recent change to day-trading margin rules", "FINRA Regulatory Notice 26-10, published April 20, 2026, replaces the old day-trading margin regime with intraday standards, effective June 4, 2026, with a firm implementation phase-in ending October 20, 2027. During that transition, do not assume the old $25,000 pattern-day-trader requirement universally applies or has universally disappeared; check your broker’s implementation.", [["FINRA Notice 26-10", "https://www.finra.org/rules-guidance/notices/26-10"], ["FINRA Rule 4210", "https://www.finra.org/rules-guidance/rulebooks/finra-rules/4210"]]]], "sRead": [["Find the original filings", "The SEC’s EDGAR search lets you find company filings and filter by form and date. A good exercise is to compare the same company’s annual, quarterly, current-event and proxy filings.", [["SEC EDGAR search", "https://www.sec.gov/edgar/search/"]]], ["The three financial statements", "A balance sheet shows assets, liabilities and equity at a point in time. The income statement measures revenue and expenses over a period. A cash-flow statement explains cash movement, which is not the same as accounting profit.", [["SEC: beginners’ guide to financial statements", "https://www.sec.gov/investor/pubs/begfinstmtguide.htm"]]], ["Notes and management discussion", "Read the footnotes and management’s discussion alongside headline figures to understand accounting choices, risks and context. Ratios lose meaning when compared across incompatible periods or business models.", [["SEC: beginners’ guide", "https://www.sec.gov/investor/pubs/begfinstmtguide.htm"]]], ["Basic ratios", "Debt-to-equity compares liabilities with equity. Operating margin compares operating income with revenue. P/E compares share price with earnings per share. Check the numerator, denominator and period, especially when earnings are negative.", [["SEC: beginners’ guide", "https://www.sec.gov/investor/pubs/begfinstmtguide.htm"]]]], "sTrade": [["A no-risk order exercise", "Use a made-up ticker to compare a market order with a price-limited order, then explain a partial fill and a non-fill. This teaches execution mechanics without opening a brokerage account or placing a real trade.", [["SEC Investor.gov: types of orders", "https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders"]]], ["Cash and margin", "FINRA Rule 4210 is the primary reference for its margin framework, and a broker’s own house requirements also matter. Borrowing adds collateral and liquidation risks, so buying power is not free money.", [["FINRA Rule 4210", "https://www.finra.org/rules-guidance/rulebooks/finra-rules/4210"]]]], "sBrokers": [["United States: BrokerCheck", "FINRA BrokerCheck provides registration and background information about brokers and firms. Search the exact legal name and read the disclosures. A profile is not a recommendation.", [["FINRA: about BrokerCheck", "https://www.finra.org/investors/investing/working-with-investment-professional/about-brokercheck"], ["BrokerCheck", "https://brokercheck.finra.org/"]]], ["United States: SIPC", "SIPC protects missing customer cash and securities at a financially troubled member broker, up to $500,000 including a $250,000 cash limit. It does not insure against market declines, and not every asset or account arrangement qualifies.", [["SIPC: what SIPC protects", "https://www.sipc.org/for-investors/what-sipc-protects"]]], ["Canada", "The Canadian Securities Administrators point to the National Registration Search, disciplinary records and your provincial or territorial regulator. Check the registration category and any conditions.", [["CSA: are they registered?", "https://www.securities-administrators.ca/investor-tools/are-they-registered/"]]], ["Australia", "ASIC’s Moneysmart has a check-before-you-invest guide with licensing and scam checks. Match the business identity and permitted activity, including contact details, rather than relying on a logo or a claimed licence.", [["Moneysmart: check before you invest", "https://moneysmart.gov.au/check-and-report-scams/check-before-you-invest"]]], ["Japan", "The Financial Services Agency publishes lists of licensed or registered financial institutions by category. Use the securities-business category; a crypto registration is not a substitute for securities permissions.", [["FSA: licensed institutions", "https://www.fsa.go.jp/en/regulated/licensed/index.html"]]], ["India", "SEBI’s intermediaries page is the official entry point for market-intermediary categories. Individual broker status and any investor-compensation rules were not verified here.", [["SEBI: intermediaries", "https://www.sebi.gov.in/intermediaries.html"]]], ["United Kingdom and Germany", "We could not read the FCA consumer-check page or the BaFin company database, so no broker names or compensation limits are given. Check your national regulator’s register directly.", null]], "sChart": [["TradingView’s own help pages", "TradingView’s Chart Questions help centre is a first-party reference for its chart features. Treat community trading ideas as opinions, not verified forecasts, and note that the full product is not free or account-free.", [["TradingView: chart help", "https://www.tradingview.com/support/categories/chart/"]]], ["Read the chart before interpreting it", "Before drawing a conclusion, identify the series, units, interval, axes and source. Compare price returns with total returns. The Reserve Bank of Australia publishes classroom worksheets on interpreting charts.", [["RBA: learning activities", "https://www.rba.gov.au/education/teacher-materials/learning-activities/"]]], ["Practice with the regulator’s tools", "The SEC publishes public investing quizzes and a compound-interest calculator. These are educational tools, not technical-analysis signals.", [["SEC: investing quizzes", "https://www.investor.gov/additional-resources/spotlight/investing-quizzes"], ["SEC: compound interest calculator", "https://www.investor.gov/financial-tools-calculators/calculators/compound-interest-calculator"]]]], "sHist": [["May 17, 1792: the Buttonwood Agreement", "The New York Stock Exchange traces its origins to the Buttonwood Agreement. This is an institutional origin, not the invention of stock trading worldwide.", [["NYSE: history", "https://www.nyse.com/history-of-nyse"]]], ["October 1929", "Federal Reserve History discusses the October 1929 stock-market crash and its monetary context. The whole Great Depression cannot be explained by one day’s price fall.", [["Federal Reserve History: 1929", "https://www.federalreservehistory.org/essays/stock-market-crash-of-1929"]]], ["October 19, 1987: Black Monday", "US stocks suffered the crash commonly called Black Monday. Federal Reserve History examines the market mechanisms and the policy response, which is useful for telling liquidity stress apart from a single-headline story.", [["Federal Reserve History: 1987", "https://www.federalreservehistory.org/essays/stock-market-crash-of-1987"]]], ["2008: the financial crisis", "Federal Reserve History traces the Great Recession and its aftermath, including financial-system stress and policy responses. Separate the recession’s dating from individual bank failures and market turning points.", [["Federal Reserve History: Great Recession", "https://www.federalreservehistory.org/essays/great-recession-and-its-aftermath"]]], ["March 15, 2020: emergency easing", "The Federal Open Market Committee lowered its target range to 0–0.25% and announced additional support measures as the pandemic disrupted economic activity. That is a policy date, not the date of any stock-market bottom.", [["Federal Reserve statement", "https://www.federalreserve.gov/newsevents/pressreleases/monetary20200315a.htm"]]]], "sRisk": [["Ownership and losses", "Company shares can lose value, and dividends are not assured. Diversification and careful research do not turn equities into insured deposits.", [["SEC Investor.gov: stocks", "https://www.investor.gov/introduction-investing/investing-basics/investment-products/stocks"]]], ["Orders are not price guarantees", "A stop order’s trigger is not a guaranteed sale price, and a limit order can stay unfilled.", [["SEC Investor.gov: types of orders", "https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders"]]], ["Protection has a specific scope", "SIPC protection concerns certain missing customer property at member firms. It does not compensate for a poor investment decision or general market losses.", [["SIPC", "https://www.sipc.org/for-investors/what-sipc-protects"]]]], "wFit": [["Example: an unexpected rate rise", "A scenario for learning, not a forecast. Higher domestic rates relative to overseas rates can support the currency, and higher yields reduce the prices of existing fixed-rate bonds. Equities may face higher discount rates, but earnings expectations and what markets already anticipated can change the outcome.", [["RBA: transmission of monetary policy", "https://www.rba.gov.au/education/resources/explainers/the-transmission-of-monetary-policy.html"], ["RBA: bonds and the yield curve", "https://www.rba.gov.au/education/resources/explainers/bonds-and-the-yield-curve.html"]]], ["Example: an oil supply disruption", "A scenario for learning. Restricted supply raises energy costs, which can lift inflation while squeezing household purchasing power and business margins. A central bank weighs persistence and expectations; a rate increase is not an automatic consequence of every oil-price move.", [["RBA: causes of inflation", "https://www.rba.gov.au/education/resources/explainers/causes-of-inflation.html"]]], ["Example: tariffs and sanctions", "A scenario for classroom discussion: a new trade restriction changes an importer’s costs and prompts sourcing changes, and currency effects depend on the broader response. No specific tariff or sanctions instrument was checked, so this is not a claim about any particular country.", [["RBA: exchange rates and the economy", "https://www.rba.gov.au/education/resources/explainers/exchange-rates-and-the-australian-economy.html"]]], ["Example: worries about a government’s debt", "A scenario for learning. Investors demand a higher yield for perceived repayment risk, which reduces an existing bond’s market value. Currency, funding and equity effects depend on the issuer and conditions. A rating change is not itself proof of default.", [["SEC Investor.gov: bonds", "https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds"]]]], "wCb": [["Federal Reserve (US)", "US statutory objectives include maximum employment, stable prices and moderate long-term interest rates. Use the Federal Open Market Committee calendar for decisions and minutes.", [["Fed: purposes and functions", "https://www.federalreserve.gov/aboutthefed/section2a.htm"], ["FOMC calendar", "https://www.federalreserve.gov/monetarypolicy/fomccalendars.htm"]]], ["European Central Bank", "The Eurosystem’s primary objective is price stability. Distinguish monetary-policy meetings from other Governing Council meetings in its calendar.", [["ECB: tasks", "https://www.ecb.europa.eu/ecb/orga/tasks/html/index.en.html"], ["ECB: meeting calendar", "https://www.ecb.europa.eu/press/calendars/mgcgc/html/index.en.html"]]], ["Bank of England", "Bank Rate is a principal monetary-policy instrument. The Monetary Policy Committee calendar supplies scheduled decision dates.", [["BoE: Bank Rate", "https://www.bankofengland.co.uk/monetary-policy/the-interest-rate-bank-rate"], ["BoE: upcoming MPC dates", "https://www.bankofengland.co.uk/monetary-policy/upcoming-mpc-dates"]]], ["Bank of Japan", "Its monetary-policy overview explains the price-stability objective. The meeting page provides schedules, summaries and minutes.", [["BoJ: monetary policy", "https://www.boj.or.jp/en/mopo/outline/index.htm"], ["BoJ: meetings and minutes", "https://www.boj.or.jp/en/mopo/mpmsche_minu/index.htm"]]], ["Swiss National Bank", "The SNB seeks price stability while taking economic developments into account. Its policy-decision archive is available; a separate future calendar was not verified.", [["SNB: mandate", "https://www.snb.ch/en/the-snb/mandates-goals"], ["SNB: decisions", "https://www.snb.ch/en/the-snb/mandates-goals/monetary-policy/decisions"]]], ["Reserve Bank of Australia", "The monetary-policy overview explains price stability and full employment. Use the Monetary Policy Board schedule rather than assuming the historical meeting pattern continues.", [["RBA: monetary policy", "https://www.rba.gov.au/monetary-policy/"], ["RBA: board meeting schedules", "https://www.rba.gov.au/schedules-events/board-meeting-schedules.html"]]], ["Bank of Canada", "The Bank explains its inflation-control framework and publishes policy announcement dates. The linked schedule is for 2026 and will need replacing for later years.", [["Bank of Canada: monetary policy", "https://www.bankofcanada.ca/core-functions/monetary-policy/"], ["2026 announcement schedule", "https://www.bankofcanada.ca/2025/08/bank-canada-publishes-2026-schedule-policy-interest-rate-announcements-other-major-publications/"]]], ["People’s Bank of China and Reserve Bank of India", "We could not retrieve the official English monetary-policy pages for either bank, so their mandates and calendars are not summarised here.", null]], "wCur": [["Exchange rates and the economy", "An exchange rate changes the domestic-currency cost of imports and the competitiveness of exports. Relative interest rates, expectations and economic conditions interact, so a single headline is not a dependable currency forecast.", [["RBA: exchange rates and the economy", "https://www.rba.gov.au/education/resources/explainers/exchange-rates-and-the-australian-economy.html"]]]], "wRates": [["Price, yield and maturity", "Distinguish a bond’s coupon from its market yield, and note the inverse relationship between price and yield for a fixed-rate bond. A yield curve compares yields across maturities. It is a market snapshot, not a guaranteed forecast.", [["RBA: bonds and the yield curve", "https://www.rba.gov.au/education/resources/explainers/bonds-and-the-yield-curve.html"]]]], "wTrade": [["International Monetary Fund", "The IMF supports international monetary cooperation through surveillance, financing and capacity development. Its role differs from a commercial bank’s.", [["IMF: about", "https://www.imf.org/en/About"]]], ["World Bank", "The World Bank’s development mission centres on reducing poverty on a livable planet. Development lending is separate from central-bank monetary policy.", [["World Bank: who we are", "https://www.worldbank.org/ext/en/who-we-are"]]], ["Bank for International Settlements", "The BIS supports central-bank cooperation and provides research and banking services for central banks. It does not set a single world policy interest rate.", [["BIS: about", "https://www.bis.org/about"]]], ["OECD", "The OECD produces comparative policy analysis, standards and data. Treat its publications as dated institutional analysis, not binding domestic law.", [["OECD: about", "https://www.oecd.org/en/about.html"]]], ["WTO, G7 and G20", "We could not open introductory pages for these bodies, so their remits and memberships are not summarised here.", null]], "wComm": [["OPEC", "OPEC describes its mission as coordinating member petroleum policies and supporting oil-market stability. A stated policy goal is not a guaranteed oil price.", [["OPEC: our mission", "https://www.opec.org/our-mission.html"]]], ["Energy outlooks", "The US Energy Information Administration’s Short-Term Energy Outlook supplies dated energy analysis and forecasts. Label forecasts and revisions as such, rather than treating them as observed production or prices.", [["EIA: Short-Term Energy Outlook", "https://www.eia.gov/outlooks/steo/"]]]], "wData": [["US labor and inflation", "The Bureau of Labor Statistics publishes its release schedule. Link the relevant release and reference period alongside any quoted figure.", [["BLS: release schedule", "https://www.bls.gov/schedule/news_release/"]]], ["US national accounts", "The Bureau of Economic Analysis publishes release dates for economic statistics. Distinguish advance estimates from later revisions.", [["BEA: schedule", "https://www.bea.gov/news/schedule"]]], ["European statistics", "Eurostat supplies an official release calendar. Distinguish EU and euro-area coverage.", [["Eurostat: release calendar", "https://ec.europa.eu/eurostat/news/release-calendar"]]], ["UK statistics", "The Office for National Statistics supplies a release calendar. Check the geographic coverage and reference period rather than assuming every release is UK-wide and current-month.", [["ONS: release calendar", "https://www.ons.gov.uk/releasecalendar"]]], ["China statistics", "The National Bureau of Statistics’ English press-release page is a primary release source. A complete forward calendar and translation lag were not verified.", [["NBS: press releases", "https://www.stats.gov.cn/english/PressRelease/"]]]], "wHist": [["1944: Bretton Woods", "The postwar monetary arrangements and institutions agreed at Bretton Woods. Distinguish the agreement from its later implementation.", [["Federal Reserve History", "https://www.federalreservehistory.org/essays/bretton-woods-created"]]], ["August 1971: gold convertibility ends", "President Nixon ended dollar convertibility into gold for foreign official holders. This is separate from every later exchange-rate reform.", [["Federal Reserve History", "https://www.federalreservehistory.org/essays/gold-convertibility-ends"]]], ["1999: the euro", "The euro began in 1999. Its initial monetary and accounting use came before the arrival of notes and coins.", [["ECB: history", "https://www.ecb.europa.eu/ecb/history-arts-culture/history/html/index.en.html"]]], ["2008: the financial crisis", "The Federal Reserve’s historical account explains financial stress, recession and policy responses without assigning every event the same date.", [["Federal Reserve History", "https://www.federalreservehistory.org/essays/great-recession-and-its-aftermath"]]], ["September 6, 2012: Outright Monetary Transactions", "The ECB announced the technical features of Outright Monetary Transactions, including conditionality. This source supports that one policy event, not a full chronology of the sovereign-debt crisis.", [["ECB press release", "https://www.ecb.europa.eu/press/pr/date/2012/html/pr120906_1.en.html"]]], ["March 15, 2020: pandemic easing", "The Federal Open Market Committee’s statement records emergency monetary easing during pandemic disruption.", [["Federal Reserve statement", "https://www.federalreserve.gov/newsevents/pressreleases/monetary20200315a.htm"]]], ["March 16, 2022: tightening begins", "The Federal Open Market Committee raised its target range and discussed inflation and the economic uncertainty associated with Russia’s invasion of Ukraine.", [["Federal Reserve statement", "https://www.federalreserve.gov/newsevents/pressreleases/monetary20220316a.htm"]]], ["1985 Plaza Accord and 1997 Asian financial crisis", "We could not open primary accounts of these events, so dates and causes are not summarised here.", null]], "eMid": [["Suggested learning order", "1. Needs, wants and choices. 2. Money and exchange. 3. Earning. 4. Saving toward a goal. 5. Spending plans. 6. Simple interest and compounding. 7. Borrowing and repayment. 8. Risk and basic diversification. 9. Markets, supply and demand. 10. Inflation and the wider economy. This is Market Files’ own teaching sequence, informed by the linked curriculum; it is not endorsed by its publisher.", [["Federal Reserve Education curriculum", "https://www.federalreserveeducation.org/teaching-resources/economics/curriculum/fref-middle-school"]]], ["Federal Reserve Education: economics curriculum", "Public lesson summaries and linked teaching materials from the Federal Reserve education network cover decisions, markets and money. Only public materials are used; account-gated teacher answer keys are not included.", [["Federal Reserve Education", "https://www.federalreserveeducation.org/teaching-resources/economics/curriculum/fref-middle-school"]]], ["Bank of England: EconoME", "The Bank of England lists free classroom resources for ages 11–16, including EconoME. Teachers outside the UK should adapt the UK examples to their learners.", [["Bank of England education", "https://www.bankofengland.co.uk/education/education-resources"]]], ["Make your own vocabulary cards", "Use the Consumer Financial Protection Bureau’s public glossary to make question-and-answer cards in class for terms like interest, saving and risk. This is a classroom activity, not an official CFPB product.", [["CFPB youth glossary", "https://www.consumerfinance.gov/consumer-tools/educator-tools/youth-financial-education/glossary/"]]], ["For teachers and parents", "The Jump$tart and Council for Economic Education national standards are a reference for grade-level expectations. Market Files has not completed a formal alignment. Use fictional budgets, and never ask pupils to share their family’s finances.", [["Jump$tart national standards (PDF)", "https://www.jumpstart.org/wp-content/uploads/2023/04/2021_Natl_Standards_Downloadable_final.pdf"]]]], "eHs": [["Suggested learning order", "1. Goals and decisions. 2. Income and taxes. 3. Budgets and net worth. 4. Saving and compound interest. 5. Credit and borrowing costs. 6. Insurance and fraud awareness. 7. Stocks, bonds and diversification. 8. Markets and institutions. 9. Inflation, employment and GDP. 10. Weighing financial claims and evidence. This is Market Files’ own teaching sequence, informed by the linked curriculum.", [["Federal Reserve Education: Making Personal Finance Decisions", "https://www.federalreserveeducation.org/teaching-resources/personal-finance/curriculum/making-personal-finance-decisions-curriculum"]]], ["Federal Reserve Education: Making Personal Finance Decisions", "The public curriculum overview describes 20 lessons across ten personal-finance concepts. Individual downloadable lessons should be checked before use.", [["Curriculum overview", "https://www.federalreserveeducation.org/teaching-resources/personal-finance/curriculum/making-personal-finance-decisions-curriculum"]]], ["CFPB youth activities", "The public activity directory offers grade filters and teacher and student materials from the US consumer-finance regulator, with no student accounts required.", [["CFPB activities", "https://www.consumerfinance.gov/consumer-tools/educator-tools/youth-financial-education/teach/activities/"]]], ["SEC quizzes and calculator", "Investor.gov offers public quizzes and a compound-interest calculator for hypothetical saving examples. Ask students to explain their assumptions and compare outcomes. No real account or investment is needed.", [["SEC investing quizzes", "https://www.investor.gov/additional-resources/spotlight/investing-quizzes"], ["Compound interest calculator", "https://www.investor.gov/financial-tools-calculators/calculators/compound-interest-calculator"]]], ["For teachers and parents", "Use fictional budgets, never ask students to disclose family finances, and see the national standards for grade-level expectations.", [["Jump$tart national standards (PDF)", "https://www.jumpstart.org/wp-content/uploads/2023/04/2021_Natl_Standards_Downloadable_final.pdf"]]]], "eCol": [["Suggested learning order", "1. Time value of money. 2. Financial statements and cash flows. 3. Risk and expected return. 4. Stocks and bonds. 5. Portfolio diversification. 6. Market institutions and incentives. 7. Insurance and banking. 8. Behavioral finance. 9. Financial crises and public policy. 10. Ethics and evidence-based analysis. This is Market Files’ own sequence, informed by the linked course.", [["Open Yale Courses: Financial Markets", "https://oyc.yale.edu/economics/econ-252"]]], ["Open Yale Courses: Financial Markets", "Yale’s public 2011 course taught by Robert Shiller is a university-level introduction to financial institutions and risk. Historical lectures need current-law context, and assigned commercial books are not free.", [["Open Yale Courses", "https://oyc.yale.edu/economics/econ-252"]]], ["Reserve Bank of Australia learning activities", "The Australian central bank publishes worksheets and teaching activities on economic indicators and how monetary policy works. They support interpreting data and explaining mechanisms, not predicting trades.", [["RBA learning activities", "https://www.rba.gov.au/education/teacher-materials/learning-activities/"]]], ["MIT problem sets", "MIT OpenCourseWare’s public directory lists finance problem sets and solutions, including present value, fixed income and common stock. Check each download before relying on it.", [["MIT OCW: Finance Theory I problem sets", "https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/pages/problem-sets/"]]], ["Using historical lectures critically", "Pair the Yale lectures with dated primary-source releases, and ask students to separate observation, forecast and interpretation. The course is a learning resource, not a current-law checklist.", [["Open Yale Courses", "https://oyc.yale.edu/economics/econ-252"]]]], "ePro": [["Suggested learning order", "1. Discounted cash-flow modelling. 2. Fixed-income valuation. 3. Equity valuation assumptions. 4. Portfolio theory. 5. CAPM and factor models. 6. Forwards and futures. 7. Options and contingent claims. 8. Capital budgeting. 9. Market efficiency and model limitations. 10. Professional ethics and conflicts. This is Market Files’ own sequence, informed by the linked course.", [["MIT OCW: Finance Theory I", "https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/"]]], ["MIT OpenCourseWare: Finance Theory I", "A public university course with problem sets. Public course pages do not make assigned books free, and no course listed here confers a credential.", [["MIT OCW", "https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/"]]], ["Federal Reserve Education and CFPB", "The Federal Reserve Education curriculum and CFPB activity directory are also open to advanced learners as a refresher on fundamentals and how consumers are taught.", [["Federal Reserve Education", "https://www.federalreserveeducation.org/teaching-resources/personal-finance/curriculum/making-personal-finance-decisions-curriculum"], ["CFPB activities", "https://www.consumerfinance.gov/consumer-tools/educator-tools/youth-financial-education/teach/activities/"]]], ["Free only", "Market Files lists only resources that are free and public, with no membership, payment or required account. Professional-credential materials that sit behind a membership or login are intentionally not listed.", null]], "ePrint": [["Pieces of Paper (Federal Reserve Education)", "A public printable classroom simulation of barter and money for younger learners, listed at 46–60 minutes. It uses classroom activity rather than real-money trading, needs no online account and has no download charge; printing supplies are separate.", [["Lesson page", "https://www.federalreserveeducation.org/teaching-resources/economics/money/pieces-of-paper"], ["Lesson PDF", "https://www.federalreserveeducation.org/resources/lessons/lesson--yen-to-trade-lesson-8.pdf"]]], ["Saving and Spending Game (Federal Reserve Education)", "A public printable card-based activity, published for grades K–5, using a fictional saving goal. It suits foundation or catch-up work. No real-money account, app or registration is needed for the PDF.", [["Lesson page", "https://www.federalreserveeducation.org/teaching-resources/personal-finance/saving/saving-and-spending-game"], ["Lesson PDF", "https://www.federalreserveeducation.org/resources/lessons/lesson--saving-and-spending-game.pdf"]]]], "eMethod": [["Spaced practice", "The US Institute of Education Sciences practice guide rates spacing learning over time as supported by moderate evidence. Revisit earlier concepts across lessons instead of one long session.", [["IES practice guide", "https://ies.ed.gov/ncee/wwc/PracticeGuide/1"]]], ["Retrieval practice", "The same guide gives strong evidence to using quizzes to re-expose students to key content. Short, low-stakes recall questions work better than a public leaderboard.", [["IES practice guide", "https://ies.ed.gov/ncee/wwc/PracticeGuide/1"]]], ["Worked examples and explaining", "The guide supports alternating worked examples with problem solving and asking deep explanatory questions. Have students explain a fictional bond or budget calculation before changing its assumptions.", [["IES practice guide", "https://ies.ed.gov/ncee/wwc/PracticeGuide/1"]]]], "eSafe": [["No real money, ever", "Everything on the Learn tab uses fictional situations or play money. Market Files does not connect lessons to brokerage execution, deposits or gambling, and there are no cash-prize leaderboards or loot boxes.", null], ["Free and public", "Resources listed here are public pages and printables with no membership, payment or required account. Competitions that require registration are left out. Market Files’ own games run in your browser and collect nothing.", null], ["Outside sites may track", "A publicly readable website can still use cookies and technical logs, and some education sites run analytics. Prefer printed classroom materials when student data exposure is a concern.", [["Example: SIFMA privacy policy", "https://www.stockmarketgame.org/privacy-policy.html"]]], ["Grade by explanation, not returns", "Use explanations, calculations and reflection as classroom assessments rather than ranking students by short-term portfolio returns. Offer printable alternatives.", [["Jump$tart national standards (PDF)", "https://www.jumpstart.org/wp-content/uploads/2023/04/2021_Natl_Standards_Downloadable_final.pdf"]]], ["Not yet listed", "Mobile apps and web simulators were not added because their current terms, ads, purchases and data handling have not been verified. They will be added after each is checked.", null]]};
const GAME_CARDS=[["Blockchain", "A shared, ordered history of blocks."], ["Private key", "A secret used to authorize spending. Anyone who gets it may control the funds."], ["Recovery phrase", "Words that can restore access to a wallet. Anyone who obtains it may obtain control, so never type it into a website."], ["Confirmation", "A transaction’s inclusion in a block, followed by additional blocks."], ["Double spend", "An attempt to spend the same funds twice."], ["Mining", "Proof-of-work block production."], ["Staking", "Committing assets to proof-of-stake validation."], ["Gas", "The unit that measures computation on Ethereum. A fee combines gas used with its price."], ["Smart contract", "A program executed under blockchain rules."], ["Stablecoin", "A token that aims to track a reference value, often a currency. The peg and any redemption mechanism carry risks."], ["Market order", "Prioritizes getting executed, without fixing the price."], ["Limit order", "Sets a price boundary, but may not execute."], ["Stop order", "Becomes a market order when triggered, so it does not guarantee the stop price."], ["T+1 settlement", "Most US securities trades settle one business day after the trade date (since May 28, 2024)."], ["Balance sheet", "Assets, liabilities and equity at a point in time."], ["Income statement", "Revenue and expenses over a period."], ["Cash-flow statement", "Cash movement, which is not the same as accounting profit."], ["P/E ratio", "Share price compared with earnings per share."], ["Dividend", "A cash distribution to shareholders. Owning a stock does not guarantee one."], ["Yield curve", "Yields compared across maturities. A market snapshot, not a guaranteed forecast."], ["Bond price and yield", "For a fixed-rate bond they move in opposite directions: when yields rise, existing bond prices fall."], ["Spot price", "A cash-market price for immediate delivery of the metal. Retail prices add premiums and other costs."], ["Gold/silver ratio", "The gold price divided by the silver price, in the same units and at the same time."], ["Futures margin", "A good-faith deposit, much smaller than the contract’s full value. Leverage magnifies gains and losses."]];
const GAME_QUIZ=[["What did the April 2024 Bitcoin halving reduce the block subsidy to?", ["6.25 BTC", "3.125 BTC", "12.5 BTC", "1.5625 BTC"], 1, "Block 840,000 cut the subsidy from 6.25 to 3.125 BTC.", "bitcoin.org/en/halving"], ["What was the Ethereum “Merge” on September 15, 2022?", ["A switch from proof of work to proof of stake", "A cap on the supply of ETH", "A merger of two exchanges", "A change to Bitcoin’s block size"], 0, "Ethereum replaced proof-of-work consensus with proof of stake.", "ethereum.org/roadmap/merge"], ["Since May 28, 2024, most US securities trades settle…", ["Same day", "One business day after the trade (T+1)", "Two business days after (T+2)", "Five business days after"], 1, "The SEC explains the move to a one-business-day settlement cycle.", "investor.gov (T+1 bulletin)"], ["What are the NYSE’s core trading hours on a normal day?", ["8:00 a.m. to 5:00 p.m. ET", "9:30 a.m. to 4:00 p.m. ET", "10:00 a.m. to 3:00 p.m. ET", "24 hours"], 1, "The core session is 9:30–16:00 Eastern; other venues and extended sessions differ.", "nyse.com/trade/hours-calendars"], ["A stop order, once triggered, becomes…", ["A limit order at the stop price", "A market order, so the price is not guaranteed", "A cancelled order", "A guaranteed sale at the stop price"], 1, "A stop order turns into a market order when triggered and does not guarantee the stop price.", "investor.gov (types of orders)"], ["How big is one COMEX gold futures contract?", ["1 troy ounce", "10 troy ounces", "100 troy ounces", "5,000 troy ounces"], 2, "Standard trading unit: 100 troy ounces. Silver is 5,000.", "CME COMEX rulebook"], ["SIPC protects up to how much per customer if a member broker fails?", ["$25,000", "$100,000", "$500,000, including a $250,000 cash limit", "Unlimited"], 2, "SIPC covers missing customer property, not market losses.", "sipc.org"], ["What happened on August 15, 1971?", ["The euro began", "Nixon suspended dollar convertibility into gold", "The NYSE was founded", "Bretton Woods was signed"], 1, "It was a central break in the Bretton Woods arrangement.", "federalreservehistory.org"], ["When market yields rise, what generally happens to an existing fixed-rate bond’s price?", ["It rises", "It falls", "It stays the same", "It doubles"], 1, "Price and yield move inversely for a fixed-rate bond.", "rba.gov.au (bonds and the yield curve)"], ["Who can control your coins if they get your recovery phrase?", ["Only the wallet maker", "Nobody, the phrase is useless alone", "Anyone who has it", "Only people in your country"], 2, "Recovery phrases can restore access, so anyone who obtains one may obtain control.", "investor.gov (crypto custody basics)"]];
const hubSrc2=s=>s&&s.length?`<p class="hub-src">Source: ${s.map(([t,u])=>`<a href="${u}" target="_blank" rel="noopener">${esc(t)}</a>`).join(' · ')} · checked ${HUB_CHECKED}</p>`:'';
const hubItems=a=>`<div class="hub-g">${a.map(([t,b,s])=>`<div class="hub-c" data-holo><h3>${esc(t)}</h3><p>${esc(b)}</p>${hubSrc2(s)}</div>`).join('')}</div>`;
const hubGap='<div style="height:20px"></div>';
const hubDL=(t,a,s)=>`<div class="hub-c" data-holo><h3>${esc(t)}</h3><dl class="hub-dl">${a.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${hubSrc2(s)}</div>`;
const hubNote=t=>`<p class="pv">${t}</p>`;
const NOT_ADVICE='Market Files is a news and media company. This is education, not financial, legal or tax advice. Check every claim against the linked source before you act on it.';
const cryptoIds=['BTC','ETH','SOL','XRP','BNB','DOGE','ADA','LINK'];
function cryptoPx(){return `${stripTiles(['BTC','ETH','SOL','XRP'])}<div style="height:28px"></div>${heatGrid(INSTR.filter(q=>cryptoIds.includes(q.id)),'Crypto heat map')}<p class="pv">Click any tile for its chart. <a href="#/crypto" style="border-bottom:1px solid var(--line2)">Open the full crypto terminal →</a></p>`}
function metalsPx(){return `${stripTiles(['XAU','XAG','GC1','SI1'])}<div style="height:28px"></div>${heatGrid(INSTR.filter(q=>['XAU','XAG','GC1','SI1','HG1','HG','CL','CL1'].includes(q.id)),'Metals and energy')}<p class="pv">Spot prices and futures prices are different things: futures carry a contract month. Click any tile for its chart. <a href="#/futures" style="border-bottom:1px solid var(--line2)">Futures hub →</a></p>`}
function stocksPx(){return `${stripTiles(['SPX','COMP','INDU','RUT'])}<div style="height:28px"></div>${heatGrid(INSTR.filter(q=>['SPX','COMP','INDU','RUT','VIX','ES1','NQ1','YM1','RTY1'].includes(q.id)),'US indexes and index futures')}<p class="pv">Click any tile for its chart. <a href="#/companies" style="border-bottom:1px solid var(--line2)">Company prices, charts and SEC filings →</a></p>`}
function worldPx(){const ids=['SPX','UKX','DAX','CAC','SX5E','NKY','HSI','SHCOMP','SENSEX','AS51','TSX','IBOV'];return `${stripTiles(['DXY','EURUSD','USDJPY','US10Y'])}<div style="height:28px"></div>${heatGrid(INSTR.filter(q=>ids.includes(q.id)),'World stock indexes')}<div style="height:20px"></div>${heatGrid(INSTR.filter(q=>['US2Y','US5Y','US10Y','US30Y','DE10Y','GB10Y','JP10Y','FR10Y','IT10Y'].includes(q.id)),'Government bond yields')}<div style="height:20px"></div>${heatGrid(INSTR.filter(q=>['DXY','EURUSD','USDJPY','GBPUSD','USDCNY','USDCHF','AUDUSD','XAU','CL'].includes(q.id)),'Currencies, gold and oil')}<p class="pv">Click any tile for its chart. <a href="#/global-finance" style="border-bottom:1px solid var(--line2)">World markets terminal →</a></p>`}
function cryptoWallets(){return hubItems(HD.walletIntro)+hubGap+hubItems(HD.wallets)+hubNote(NOT_ADVICE)}
function cryptoTerms(){return `<div class="hub-g">${hubDL('Bitcoin vocabulary',HD.termsBtc,[['bitcoin.org vocabulary','https://bitcoin.org/en/vocabulary']])}${hubDL('Ethereum glossary',HD.termsEth,[['ethereum.org glossary','https://ethereum.org/glossary/']])}</div>`}
function cryptoHowto(){return hubItems(HD.howto)+hubGap+`<div class="hub-c" data-holo><h3>Official tax pages</h3><p>These are official reference pages, not determinations of rates, exemptions or anyone’s tax bill. The EU has no single personal crypto-tax treatment; use the authority for your country of residence. Pages for Canada, Australia, Singapore and Germany could not be verified.</p><ul>${HD.tax.map(([t,u])=>`<li><a href="${u}" target="_blank" rel="noopener" style="border-bottom:1px solid var(--line2)">${esc(t)}</a></li>`).join('')}</ul><p class="hub-src">checked ${HUB_CHECKED}</p></div>`}
const CRYPTO_RISK_NOTE='Crypto assets are volatile and can lose all of their value. Exchanges and custodians can fail, and stolen or mis-sent crypto is usually unrecoverable. '+NOT_ADVICE;

/* Education: original games, no accounts, nothing stored or sent */
function gamesHTML(){return `<div class="hub-g">
  <div class="hub-c gm" data-holo><h3>Flashcards</h3><p>Learn the vocabulary of markets. Tap “Again” on cards you miss and they come back soon.</p><div id="g-fc" class="gm-box"></div></div>
  <div class="hub-c gm" data-holo><h3>10-question market quiz</h3><p>Every answer is checked against a primary source and the quiz tells you which one.</p><div id="g-qz" class="gm-box"></div></div>
  <div class="hub-c gm" data-holo><h3>Compound interest explorer</h3><p>Move the sliders and watch time and rate do the work. This is a hypothetical example, not a forecast or a promise of returns.</p><div id="g-ci" class="gm-box"></div></div></div>
  <p class="pv">All three games run in your browser with play numbers only. No sign-up, no accounts and no money. Nothing you do here is stored or sent anywhere.</p>`}
function gameFlash(el){const deck=GAME_CARDS;let q=[],done=0,total=0,again=0,show=false;
  const start=()=>{q=deck.map(c=>({k:c[0],a:c[1]}));for(let i=q.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[q[i],q[j]]=[q[j],q[i]]}total=q.length;done=0;again=0;show=false;draw()};
  const draw=()=>{if(!q.length){el.innerHTML=`<div class="gm-card"><p class="gm-k mono">DONE</p><h4>You went through all ${total} cards.</h4><p class="gm-a">${again?`You asked to see ${again} card${again>1?'s':''} again before getting them. That repeat practice is what makes learning stick.`:'You knew every card on the first try.'}</p></div><div class="gm-btns"><button class="btn gm-ok" data-a="restart">Play again</button></div>`;return}
    const c=q[0];el.innerHTML=`<div class="gm-top mono"><span>${done} / ${total} learned</span><span>${again} repeated</span></div><div class="gm-card"><p class="gm-k mono">TERM</p><h4>${esc(c.k)}</h4>${show?`<p class="gm-a">${esc(c.a)}</p>`:'<p class="gm-a dim">Say the meaning to yourself first, then check.</p>'}</div><div class="gm-btns">${show?'<button class="btn" data-a="again">Again</button><button class="btn gm-ok" data-a="ok">Got it</button>':'<button class="btn gm-ok" data-a="show">Show answer</button>'}</div>`};
  el.onclick=e=>{const b=e.target.closest('[data-a]');if(!b)return;const a=b.dataset.a;if(a==='show')show=true;else if(a==='ok'){q.shift();done++;show=false}else if(a==='again'){const c=q.shift();again++;q.splice(Math.min(3,q.length),0,c);show=false}else if(a==='restart'){start();return}draw()};start()}
function gameQuiz(el){let order=[],i=0,score=0,picked=-1;
  const start=()=>{order=GAME_QUIZ.map((_,k)=>k);for(let k=order.length-1;k>0;k--){const j=Math.floor(Math.random()*(k+1));[order[k],order[j]]=[order[j],order[k]]}i=0;score=0;picked=-1;draw()};
  const draw=()=>{if(i>=order.length){el.innerHTML=`<div class="gm-card"><p class="gm-k mono">RESULT</p><h4>${score} out of ${order.length}</h4><p class="gm-a">${score===order.length?'Perfect score.':score>=7?'Strong. Re-read the ones you missed.':'Good start. Try the flashcards, then play again.'}</p></div><div class="gm-btns"><button class="btn gm-ok" data-a="restart">Play again</button></div>`;return}
    const [qq,opts,ans,why,src]=GAME_QUIZ[order[i]];
    el.innerHTML=`<div class="gm-top mono"><span>Question ${i+1} of ${order.length}</span><span>Score ${score}</span></div><div class="gm-card"><h4>${esc(qq)}</h4><div class="gm-opts">${opts.map((o,k)=>`<button class="gm-opt${picked<0?'':k===ans?' right':k===picked?' wrong':''}" data-p="${k}" ${picked<0?'':'disabled'}>${esc(o)}</button>`).join('')}</div>${picked<0?'':`<p class="gm-a"><b>${picked===ans?'Correct.':'Not quite.'}</b> ${esc(why)} <span class="dim mono">Source: ${esc(src)}</span></p>`}</div><div class="gm-btns">${picked<0?'':`<button class="btn gm-ok" data-a="next">${i+1<order.length?'Next question':'See result'}</button>`}</div>`};
  el.onclick=e=>{const p=e.target.closest('[data-p]');if(p&&picked<0){picked=+p.dataset.p;if(picked===GAME_QUIZ[order[i]][2])score++;draw();return}const b=e.target.closest('[data-a]');if(!b)return;if(b.dataset.a==='next'){i++;picked=-1;draw()}else if(b.dataset.a==='restart')start()};start()}
function gameCompound(el){const f=n=>n.toLocaleString('en-US',{maximumFractionDigits:0});
  el.innerHTML=`<div class="gm-in"><label>Starting amount: $<b id="ci-a-v">1,000</b><input type="range" id="ci-a" min="0" max="10000" step="100" value="1000"></label><label>Add each month: $<b id="ci-m-v">100</b><input type="range" id="ci-m" min="0" max="1000" step="25" value="100"></label><label>Yearly growth rate: <b id="ci-r-v">6</b>%<input type="range" id="ci-r" min="0" max="12" step="0.5" value="6"></label><label>Years: <b id="ci-y-v">20</b><input type="range" id="ci-y" min="1" max="40" step="1" value="20"></label></div><div class="gm-card"><p class="gm-k mono">HYPOTHETICAL BALANCE AFTER <span id="ci-yy">20</span> YEARS</p><h4 id="ci-out"></h4><p class="gm-a" id="ci-sub"></p><div class="ci-bars" id="ci-bars"></div></div>`;
  const run=()=>{const a=+$('#ci-a',el).value,m=+$('#ci-m',el).value,r=+$('#ci-r',el).value/100,y=+$('#ci-y',el).value;$('#ci-a-v',el).textContent=f(a);$('#ci-m-v',el).textContent=f(m);$('#ci-r-v',el).textContent=r*100;$('#ci-y-v',el).textContent=y;$('#ci-yy',el).textContent=y;
    let b=a,paid=a;const yr=[];for(let k=1;k<=y;k++){for(let mo=0;mo<12;mo++){b=b*(1+r/12)+m;paid+=m}yr.push(b)}
    $('#ci-out',el).textContent='$'+f(b);$('#ci-sub',el).textContent=`You would have put in $${f(paid)}; the other $${f(Math.max(0,b-paid))} would be growth. Monthly compounding, constant rate, no taxes or fees. Real returns vary and can be negative.`;
    const mx=Math.max(...yr,1);$('#ci-bars',el).innerHTML=yr.map(v=>`<i style="height:${Math.max(3,v/mx*100)}%"></i>`).join('')};
  el.oninput=run;run()}
