/* ===================================================================================
   v5 — editorial fronts, archival photos, full-screen place dossier, welcome/goodbye,
   and the biggest-stories band. Every photo is the lead image of the exact Wikipedia article
   (free-licence images only); every headline is real (publisher feeds) or a Market
   Files file; every number is real or shown as a dash.
   =================================================================================== */
const LIVE_SITE=!!window.MF_CONFIG;
/* ---------- Wikipedia: exact-article lead images (free licences only) ---------- */
const WIKI={};
async function wikiBatch(titles){const need=[...new Set(titles)].filter(t=>t&&!(t in WIKI));
  for(let i=0;i<need.length;i+=40){const chunk=need.slice(i,i+40);
    try{const u='https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&redirects=1&prop=pageimages&piprop=thumbnail&pithumbsize=1280&titles='+encodeURIComponent(chunk.join('|'));
      const j=await (await fetch(u)).json();const q=j.query||{};const to={};chunk.forEach(t=>to[t]=t);
      [...(q.normalized||[]),...(q.redirects||[])].forEach(n=>{for(const k in to)if(to[k]===n.from)to[k]=n.to});
      const by={};Object.values(q.pages||{}).forEach(p=>by[p.title]=p);
      chunk.forEach(t=>{const p=by[to[t]];WIKI[t]=p&&p.thumbnail?{src:p.thumbnail.source,title:p.title,url:'https://en.wikipedia.org/wiki/'+encodeURIComponent(p.title.replace(/ /g,'_'))}:null})}
    catch(e){chunk.forEach(t=>{WIKI[t]=null})}}}
const wimg=(t,cls='')=>t?`<img class="wimg ${cls}" data-wiki="${esc(t)}" alt="" decoding="async" referrerpolicy="no-referrer">`:'';
async function hydrateWiki(root=document){const els=[...root.querySelectorAll('img[data-wiki]:not([data-wd])')];if(!els.length)return;
  els.forEach(e=>e.dataset.wd=1);await wikiBatch(els.map(e=>e.dataset.wiki));
  els.forEach(e=>{const r=WIKI[e.dataset.wiki];if(!r){e.remove();return}e.onload=()=>e.classList.add('ok');e.onerror=()=>e.remove();e.src=r.src;e.alt=r.title;
    const cr=e.closest('[data-wcr]')&&e.closest('[data-wcr]').querySelector('.wcredit');if(cr){cr.innerHTML=`Image: <a href="${r.url}" target="_blank" rel="noopener">${esc(r.title)}</a>`;cr.hidden=false}})}
/* Time Machine rows: swap the curated photo for the event's own lead image when one exists. */
const EVIO=('IntersectionObserver' in window)?new IntersectionObserver(es=>es.forEach(en=>{if(en.isIntersecting){EVIO.unobserve(en.target);evPhoto(en.target)}}),{rootMargin:'300px'}):null;
async function evPhoto(fig){const q=fig.dataset.evq;if(!q||!LIVE_SITE)return;const r=await wikiSearch(q,1);if(!r||!r.img||!fig.isConnected)return;
  const im=new Image();im.referrerPolicy='no-referrer';im.decoding='async';im.alt=r.title;im.onload=()=>{if(!fig.isConnected)return;fig.querySelectorAll('img').forEach(x=>x.remove());fig.appendChild(im);requestAnimationFrame(()=>im.classList.add('ok'))};im.src=r.img}
function scanEvPhotos(){document.querySelectorAll('.ev-ph[data-evq]:not([data-evw])').forEach(f=>{f.dataset.evw=1;EVIO?EVIO.observe(f):evPhoto(f)})}
new MutationObserver(()=>{clearTimeout(scanEvPhotos.t);scanEvPhotos.t=setTimeout(scanEvPhotos,120)}).observe(document.documentElement,{childList:true,subtree:true});
/** Search Wikipedia for the best page for `q`; returns title, short extract, lead image and URL. */
const WS={};
async function wikiSearch(q,sent=3){const k=q+'|'+sent;if(k in WS)return WS[k];let r=null;
  try{const u='https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&generator=search&gsrnamespace=0&gsrlimit=1&gsrsearch='+encodeURIComponent(q)+'&prop=extracts|pageimages&exintro=1&explaintext=1&exsentences='+sent+'&piprop=thumbnail&pithumbsize=1280';
    const j=await (await fetch(u)).json();const p=j.query&&Object.values(j.query.pages)[0];
    if(p)r={title:p.title,extract:(p.extract||'').replace(/\s*\([^()]*\)/,'').trim(),img:p.thumbnail?p.thumbnail.source:null,url:'https://en.wikipedia.org/wiki/'+encodeURIComponent(p.title.replace(/ /g,'_'))}}catch(e){}
  return WS[k]=r}

/* Company 'about' block in the detail panel: Wikipedia photo/logo and a two-sentence summary, shown only when the article's title matches the company. */
async function coAbout(q){const r=await wikiSearch(q.name+' company',2);const first=q.name.split(/[ .,’']/)[0].toLowerCase();
  if(!r||!r.extract||!r.title.toLowerCase().includes(first))return;
  const v=$('#inst-b .side-v'),h=$('#inst-b .side-h');if(!v||!h||v.dataset.id!==q.id||$('#inst-b .co-ab'))return;
  h.insertAdjacentHTML('afterend',`<div class="co-ab">${r.img?`<img src="${esc(r.img)}" alt="${esc(r.title)}" loading="lazy" referrerpolicy="no-referrer">`:''}<p>${esc(r.extract)}</p><a class="mono" href="${esc(r.url)}" target="_blank" rel="noopener">Wikipedia · ${esc(r.title)} ↗</a></div>`);
  const im=$('#inst-b .co-ab img');if(im)im.onerror=()=>im.remove()}

